\label{main-thm} 
 Let $\Sigma_0$ be a smooth strictly convex capillary hypersurface in $\overline{\mathbb{R}^{n+1}_+}$ and $\theta\in(0,  \pi /2)$, then  flow \eqref{c-Gauss curvature flow} has a smooth solution $\Sigma_t\coloneqq X(\cdot,t)$, which is strictly convex capillary hypersurface for all $t\in[0,T^*)$, where $T^*\coloneqq \frac{ {\rm{Vol}}(\widehat{\Sigma}_0)}{ (n+1){\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})}  .$  As $t\rightarrow T^{\ast}$, then $\Sigma_t$ shrink to a point $p\in \partial{\mathbb{R}^{n+1}_{+}}$.  Moreover, the rescaled capillary hypersurfaces 
 \begin{eqnarray}\label{rescaled-hypersurface}
  \widetilde{\Sigma}_{t}\coloneqq \left(\frac{ {\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})}{ {\rm{Vol}}(\widehat\Sigma_t )}\right)^{\frac{1}{n+1}}(\Sigma_{t}-p),
 \end{eqnarray}
 converge to a smooth, strictly convex capillary hypersurface $\Sigma_\infty\subset \overline{\mathbb{R}^{n+1}_+}$ as  $t\to +\infty$, which is a solution to \eqref{soliton0}.

\label{defn-capillary-support}
Let $\widehat\Sigma\in \mathcal{K}_\theta$, the support function $h_{z}$ of ${\Sigma}$ with respect to $z\in\widehat{\Sigma}$ is defined by
 \begin{eqnarray*}
      h_{z} (\xi)\coloneqq   \max _{X\in \Sigma}\< \xi-\cos\theta e, X-z\>, \quad \xi\in \mathcal{C}_{\theta}.
	\end{eqnarray*}
The capillary support function of $\Sigma$ with respect to $z$ is defined by
 \begin{eqnarray}\label{capillary support}
     u_{z}(\xi)\coloneqq \frac{h_{z}(\xi)}{\ell (\xi)}, ~~~~\xi\in \mathcal{C}_\theta.
 \end{eqnarray}

Let $\widehat{\Sigma}\in \mathcal{K}_{\theta}$ and $\theta \in (0, \pi/2)$. Then there hold
    \begin{eqnarray}\label{inner radius}
         (1-\cos\theta )\rho_{-}(\widehat{\Sigma}, \theta)\leq \rho_{-}(\widehat{\Sigma})\leq \sin\theta \rho_{-}(\widehat{\Sigma}, \theta),
    \end{eqnarray}
    and 
    \begin{eqnarray}\label{outer radius}
          (1-\cos\theta )\rho_{+}(\widehat{\Sigma}, \theta)\leq \rho_{+}(\widehat{\Sigma})\leq \sin\theta \rho_{+}(\widehat{\Sigma}, \theta),
    \end{eqnarray}

We begin by proving that \eqref{inner radius} holds.
 From the definition of capillary inner radius, there exists a spherical cap $\mathcal{C}_{r_{0}, \theta}(x_{0})$ with radius $r_{0}=\rho_{-}(\widehat{\Sigma}, \theta)$, such that $\widehat{\mathcal{C}_{r_{0}, \theta}(x_{0})}$ is contained in $\widehat{\Sigma}$. It is obvious that $$B_{(1-\cos\theta)r_{0}}^{+}(x_{0})\subseteq \widehat{\mathcal{C}_{r_{0}, \theta}(x_{0})}\subseteq \widehat{\Sigma},$$
 which implies 
    \begin{eqnarray*}
        (1-\cos\theta )\rho_{-}(\widehat{\Sigma}, \theta)\leq \rho_{-}(\widehat{\Sigma}).
    \end{eqnarray*}
On the other hand, from \cite[Proposition 2.4, Eq. (2.26)]{SW}, we get
\begin{eqnarray*}
    \rho_{-}(\widehat{\Sigma}, \theta)\geq \frac{\rho_{-}(\widehat{\Sigma})}{\sin\theta}.
\end{eqnarray*}
Hence, this completes the proof of \eqref{inner radius}. Similarly, by applying \cite[Proposition 2.4, Eq.~(2.27)]{SW}, the proof of \eqref{outer radius} follows in an analogous manner.

\label{def-pola}
Given $\widehat\Sigma\in\mathcal{K}_\theta^{\circ}$, its capillary radial function $\rho_{\widehat\Sigma}\colon  \mathcal{C}_\theta\to [0,+\infty)$ is defined by
	\begin{eqnarray*}
	\rho_{\widehat{\Sigma}}(\xi)\coloneqq  \sup \left\{ \lambda \geq 0\,|\, \lambda \xi \in \widehat\Sigma  \right\} ,  \quad  \xi \in \mathcal{C}_{\theta }.
\end{eqnarray*}

Given $\widehat\Sigma\in \mathcal{K}_\theta^\circ$ and $z\in {\rm{int}}(\widehat{\partial\Sigma})$. Denote $\rho_{z} \coloneqq \rho_{\widehat{\Sigma}_{z}^{\ast}}$ be the capillary radial function of $\widehat{\Sigma}_{z}^{\ast}$. Then there holds 
    \begin{eqnarray*}
    \rho_{z}(\xi)=\frac{1}{u_{z}(\xi)}, ~~~~\forall \xi\in \mathcal{C}_\theta.
    \end{eqnarray*}

\label{prop-volume-polar-body}
The volume of the capillary polar body $\widehat{\Sigma}^{*}_{z}$ satisfies
 \begin{eqnarray}
{\rm{Vol}}(\widehat{\Sigma}^*_{z}) =
 \frac{1}{n+1}\int _{\mathcal{C}_{\theta }} \frac {\ell(\xi)} {u^{n+1}_{z}(\xi)} d\sigma=\frac{1}{n+1}\int_{\mathcal{C}_{\theta}}\frac{\ell^{n+2}(\xi)}{h^{n+1}_{z}(\xi)}d\sigma, \label{vol}
\end{eqnarray}
where $d\sigma$ is the standard area element on $\mathcal{C}_\theta$.

From the co-area formula and the  0-homogeneity property of $\nabla F^\circ_{\theta}$, we compute
\begin{eqnarray}
{\rm{Vol}}(\widehat{\Sigma}^*_{z}) &=& \int_{-\infty}^\infty \int_{\{F^\circ_{\theta}=r\}}\frac {\chi_{\{r u_{z}(\xi)\le 1\}}} {|\nabla F^\circ_{\theta}(\xi)|} d\sigma dr
=  \int_{-\infty}^\infty \int_{\{F^\circ_{\theta}=1\}} r^n \frac {\chi_{\{ru_{z}(\xi)\le 1\}}}
 {|\nabla F^{\circ}_{\theta}(\xi)|} d\sigma dr\notag \\
 &=&\int_{\mathcal{C}_\theta} \frac 1{|\nabla F^\circ_{\theta}(\xi)|}\int_0^{\frac 1{u_{z}(\xi)}} r^n dr d\sigma\notag \\
 &=& \frac 1{n+1} \int_{\mathcal{C}_\theta}  \frac 1{|\nabla F^\circ_{\theta}(\xi)|}\frac 1{u^{n+1}_{z}(\xi)} d\sigma .\label{polar volume}
\end{eqnarray}
From \eqref{eq:gradF}, we obtain 
\begin{eqnarray}| \nabla F^{\circ}_{\theta}(\xi )| = \frac{1}{\sin \theta} \frac{1}{\sqrt{|\xi |^2 +\cot^2\theta \<e,\xi\>^2}}= \frac 1 \ell. 
\label{norm gredient}
\end{eqnarray}
Inserting \eqref{norm gredient} into \eqref{polar volume}, the first equality of \eqref{vol} follows, while the second equality follows directly by combining with \eqref{capillary support}. This completes the proof.

\label{pro-santalo}
    The capillary Santal\'o point $z_{s}$ is unique and lies in ${\rm{int}}(\widehat{\partial\Sigma})$. Moreover, there holds
\begin{eqnarray}\label{santalo-point-ortho}
    \int_{\mathcal{C}_{\theta}}\frac { \xi_i}{u_{z_s}^{n+2}(\xi)} d\sigma=0,\quad~ \forall  ~ i=1,\cdots, n,
    \end{eqnarray}where $\xi_i\coloneqq \<\xi, E_i\>$, with $\{E_i\}_{i=1}^n$ denoting the horizontal coordinate vectors of $\mathbb{R}^{n+1}_+$.

\label{prop-santalo-ineq}
Given $\widehat{\Sigma}\in \mathcal{K}_{\theta}$ and  $\theta\in(0,\pi/2)$, then there holds
   \begin{eqnarray}\label{BS-ineu}
\inf\limits_{z\in {\rm{int}}(\widehat{\partial\Sigma})}{\rm{Vol}}(\widehat{\Sigma}) {\rm{Vol}}(\widehat{\Sigma}^*_{z}) \le  \frac{1}{2}{\rm{Vol}}(\mathbb{B}^{n+1})^{2}.
\end{eqnarray}

Let $R\colon \overline{\mathbb{R}^{n+1}_+} \to \mathbb{R}^{n+1}$ be the reflection map,  defined by $$ R(x)\coloneqq (x_{1},\cdots, x_{n}, -x_{n+1}), \quad x\in\overline{\mathbb{R}^{n+1}_{+}}.$$
 Let $V=\Sigma\cup R(\Sigma)$ and $\Omega$ be the bounded domain enclosed by $V$. Then $\Omega$ is symmetric with respect to the hyperplane $\partial\mathbb{R}^{n+1}_+$. Denote by $\Omega^{\ast}_z$ the polar body of the convex body $\Omega$ with respect to the point $z \in {\rm{int}}(\Omega)$, defined by
\begin{eqnarray*}
\Omega^{\ast}_{z}\coloneqq \left\{X+z\in \mathbb{R}^{n+1} \mid r \widehat h_{z}(\eta)\leq 1, ~ {\rm{where}} ~ X=r\eta ~ {\rm{with}} ~ \eta\in \mathbb{S}^{n} \right\},
\end{eqnarray*} where $\widehat h_z\colon \mathbb{S}^n\to \mathbb{R}$ is the usual support function of $\Omega$ with respect to $z$. From \cite[Section 10.5 and Eq. (10.28)]{Sch} (see also \cite{San}),  
we know there exists a unique point (Santal\'o point) $z_{0}\in \rm{int}(\Omega)$ such that 
\begin{eqnarray*}
    {\rm{Vol}}\left(\Omega_{z_{0}}^{\ast}\right)=\inf \limits_{z\in \rm{int}(\Omega)}{\rm{Vol}}\left(\Omega^{\ast}_{z}\right),
\end{eqnarray*} 
and the Blaschke-Santal\'o inequality  
\begin{eqnarray}\label{class-BS}
    {\rm{Vol}}(\Omega){\rm{Vol}}
    \left(\Omega_{z_{0}}^{\ast}\right)\leq {\rm{Vol}}(\mathbb{B}^{n+1}) ^{2}.
\end{eqnarray}
 From \cite[Eq. (10.22)]{Sch} (or \cite[Lemma 2]{MP}), there holds 
    \begin{eqnarray}\label{sym}
        0=\int_{\mathbb{S}^{n}}\frac{\eta_{i}}{\widehat h^{n+1}_{z_0}(\eta)}d\eta,\quad 1\leq i\leq n+1.
    \end{eqnarray}
In particular, the symmetry of $\Omega$ with respect to $\partial \mathbb{R}^{n+1}_+$ implies 
    \begin{eqnarray}\label{zs}
        z_{0}\in {\rm{int}}(\Omega) \cap \partial {\mathbb{R}^{n+1}_{+}}={\rm{int}}({\widehat{\partial \Sigma}}).
    \end{eqnarray}
Since $\ell<1$, from the definition of $\widehat{\Sigma}^{\ast}_{z_{0}}$ and $\Omega_{z_{0}}^{\ast}$, we deduce that $\widehat{\Sigma}^{\ast}_{z_{0}}\subseteq \Omega^{\ast}_{z_{0}}$, and hence
\begin{eqnarray*}                     
    {\rm{Vol}}(\widehat{\Sigma}_{z_{0}}^{\ast})\leq {\rm{Vol}}(\Omega_{z_{0}}^{\ast}).
\end{eqnarray*}
Together with \eqref{class-BS} and \eqref{zs}, 
  we derive  
\begin{eqnarray*}
    \inf\limits_{z\in {\rm{int}}(\widehat{\partial\Sigma})}{\rm{Vol}}(\widehat{\Sigma}){\rm{Vol}}(\widehat{\Sigma}^{\ast}_{z})&\leq&  {\rm{Vol}}(\widehat{\Sigma}){\rm{Vol}}(\widehat{\Sigma}^{\ast}_{z_{0}})\\
    &\leq&  \frac{1}{2}{\rm{Vol}}(\Omega){\rm{Vol}}
    \left(\Omega_{z_{0}}^{\ast}\right) \\& \leq & \frac{1}{2} {\rm{Vol}}(\mathbb{B}^{n+1})^{2}.
\end{eqnarray*} 
This completes the proof of \eqref{BS-ineu}.

\label{conj-sharp-capillary-B-S-ineq}  {\it Given $\widehat{\Sigma}\in \mathcal{K}_{\theta}$ and $\theta\in (0,\pi)$, then there holds
\begin{eqnarray*}
\inf\limits_{z\in {\rm{int}}(\widehat{\partial\Sigma})}{\rm{Vol}}(\widehat{\Sigma}) {\rm{Vol}}(\widehat{\Sigma}^{*}_{z}) \le    {\rm{Vol}}(\widehat{\mathcal{C}_{\theta }})  ^2.                                 
\end{eqnarray*}
Equality holds if and only if $\Sigma$ is a spherical cap. }

\label{prop-scalar equ}
	Let $\Sigma_t$ be a strictly convex solution to flow \eqref{c-Gauss curvature flow} for $t\in [0, T^*)$ and $\theta\in(0, \pi)$,   then its support function $h(\cdot,t)\colon \mathcal{C}_\theta\to \mathbb{R}$  satisfies 
\begin{eqnarray}\label{support fun eq. of capillary alpha-GCF} \left\{
\begin{array}{llll}
  \partial_t h ~ [\det(\nabla^2 h+h\sigma)]&=&-(\sin^2\theta+\cos\theta \<\xi,e\>)   & \text{ in } \mathcal{C}_\theta\times[0,T^*),\\ 
	\nabla_\mu h&=& \cot\theta h & \text{ on } \partial \mathcal{C}_\theta \times [0, T^*), \\
 h(\cdot,0) &=& h_0(\cdot)  & \text{ on } \mathcal{C}_\theta, \end{array}  \right.
\end{eqnarray} where  $\mu$ is the unit outward normal of $\partial \mathcal{C}_\theta\subset  \mathcal{C}_\theta$ and $h_0$ is support function of $\Sigma_0$.

\label{evo-h}
    Along  flow \eqref{support fun eq. of capillary alpha-GCF}, the functions $h$ and $u$ satisfy  
        \begin{eqnarray}\label{h evolution GCF 1}
      \mathcal{L} h= K \ell (hH-n-1),
    \end{eqnarray}  and \begin{eqnarray}\label{h bar evolution GCF}
\mathcal{L}  u= 2 K a^{ij} \nabla_{i}u  \nabla_{j}\ell -(n +1)K+  K H u.
    \end{eqnarray}
Along  $\partial \mathcal{C}_\theta$,             
  \begin{eqnarray}\label{robin of h}
        \nabla_\mu h =\cot\theta h,
    \end{eqnarray} 
    and 
     \begin{eqnarray}\label{robin of bar h}
        \nabla_\mu u =0. 
    \end{eqnarray}

First, we prove \eqref{h evolution GCF 1} and  \eqref{h bar evolution GCF}. Let $\{e_i\}_{i=1}^n$ be an orthonormal frame on $\mathcal{C}_\theta$ such that $e_n=\mu$.  Using  Eq. \eqref{h evolution GCF}, we have 
\begin{eqnarray*}
    \mathcal{L} h&=&\partial_t h- K \ell a^{ij} \nabla_{ij} h=-K \ell - K \ell a^{ij} (a_{ij}-h\delta_{ij}).
\end{eqnarray*} 
Since $a^{ij}\delta_{ij}=H$, we conclude that \eqref{h evolution GCF 1} holds.

A direct computation yields
\begin{eqnarray}\label{h bar evo GCF 2}
    \mathcal{L} u&=& \frac{\mathcal{L} h}{\ell} + K\ell a^{ij} \left( \frac{ 2\nabla_{i}h\nabla_{j} \ell}{\ell^2} +\frac{ h\nabla_{i}\nabla_{j}\ell}{\ell^2}-\frac{2h \nabla_{i}\ell \nabla_{j}\ell}{\ell^3}\right).
\end{eqnarray}
Since
\begin{eqnarray}\label{ell ij}
    \nabla_{i}\nabla_{j}\ell+\ell \delta_{ij}=-\cos\theta \<\xi-\cos\theta e,e\>\delta_{ij}+\ell \delta_{ij}= \delta_{ij},
\end{eqnarray} substituting \eqref{h evolution GCF 1} and \eqref{ell ij} into     \eqref{h bar evo GCF 2}, we get \eqref{h bar evolution GCF}.

Next, we derive the boundary conditions \eqref{robin of h} and \eqref{robin of bar h}.
Since $D_{e_i}X$ is tangent to $\Sigma$ at $X(\xi)$, we have
  	\begin{eqnarray*}
			\<\nu (X),D_{e_i}X\>=0,\quad 1\leq i\leq n.
		\end{eqnarray*}
		If $\xi\in \partial \mathcal{C}_{\theta}$, then $X(\xi) \in \partial \overline{\mathbb{R}^{n+1}_+}$. From \eqref{co-normal bundle}, we obtain
		\begin{eqnarray*}
			\<\mu,X\>&=&\< \sin\theta e+\cos\theta \overline{\nu},X\>=\cos\theta \<\overline{\nu} ,X\>\\&=&\cos\theta \<\cos\theta \mu+\sin \theta \nu(X),X\>=\cos^2\theta \<\mu, X\>+\sin\theta\cos\theta h,
		\end{eqnarray*}
        which implies  that
		\begin{eqnarray*}
			\<\mu,X\>=\cot\theta h.
		\end{eqnarray*} 
        Differentiating the support function $h$ gives
		\begin{eqnarray*}
			\nabla_{{\mu}}h&=&\< D_\mu T^{-1}(\xi ), X\>+\< T^{-1}(\xi ),D_\mu X\>
			\\&=& \<D_\mu\xi,  X\>= \<\mu,X\>,
		\end{eqnarray*}
		where $T^{-1}(\xi)\coloneqq  \nu (X(\xi))$ is the unit normal at $X(\xi)$. 
	Combining the above results yields
		\begin{eqnarray*} 
			\nabla_{{\mu}}h=\cot\theta h. 
		\end{eqnarray*}
Using \eqref{co-normal bundle} again, we have
  \begin{eqnarray}\notag 
      \nabla_\mu (\sin^2\theta+\cos\theta\<\xi,e\>)&=& \cos\theta \<\mu,e\>=\cos\theta \sin\theta \\&= & \cot\theta (\sin^2\theta+\cos\theta\<\xi,e\>).\label{robin of xi,e} 
  \end{eqnarray}
Consequently, \eqref{robin of bar h} can be derived from \eqref{robin of xi,e} and \eqref{robin of h}.

\label{evo of K}
    Along  flow \eqref{support fun eq. of capillary alpha-GCF}, there holds
  \begin{eqnarray}\label{K evol GCF}
      \mathcal{L} K= 2 Ka^{ij}\nabla_{i}K \nabla_{j}\ell+K^{2} H.
  \end{eqnarray}
On $\partial\mathcal{C}_\theta$,
\begin{eqnarray}\label{robin of K}
        \nabla_\mu K  =0 .  
    \end{eqnarray}

\label{lower bound of K}
    Let $K_0$ be the Gauss curvature of initial strictly convex capillary  hypersurface $\Sigma_0$ with $\theta\in(0,\pi)$, and $\Sigma_t$ solves \eqref{c-Gauss curvature flow} on $[0,T^*)$.  Then there holds
    \begin{eqnarray}\label{lower bdd K}
        K (\xi, t) \geq \min_{\mathcal{C}_\theta} K_0,
    \end{eqnarray} for all $(\xi,t)\in \mathcal{C}_\theta \times [0,T^*)$.

From Proposition \ref{evo of K},  we see 
\begin{eqnarray*}
    \mathcal{L} K \geq 0 ~~~\text{ mod } \nabla K ,~~ \text{ in } \mathcal{C}_\theta,
\end{eqnarray*}
and $\nabla_\mu K=0$ on $\partial \mathcal{C}_\theta$. Then \eqref{lower bdd K} follows directly from the maximum principle.

\label{upper bound of K}
Let $\Sigma_t$ be the solution of flow \eqref{c-Gauss curvature flow}  on $[0,T^*)$ with $\theta \in (0,\pi)$. If the capillary inner radius $\rho_-(\widehat\Sigma_t,\theta)$ of $\Sigma_t$ has a uniform positive lower bound $\varepsilon_0>0$,  then there exists a positive constant $C$, depending only on $\frac{1}{\varepsilon_0}$ and the initial data, such that
    \begin{eqnarray*}
  K(\xi,t) \leq C ,
    \end{eqnarray*}
for all $(\xi,t)\in \mathcal{C}_\theta \times [0,T^*)$.

First,  if the capillary inner radius of $\widehat\Sigma_t $ has a uniformly positive lower bound $\varepsilon_{0}$ for all $t\in[0, T^*)$, then according to  Remark \ref{rem-cap-inner-radius},
there exists a point $z_{0}\in \text{int}( \widehat{\partial\Sigma_{t}})$, such that $u_{z_0}(\xi, t)\geq \varepsilon_0 $ for all $(\xi,t)\in\mathcal{C}_\theta\times [0, T^*)$. Without loss of generality, we assume that $z_{0}$ is the origin  and  consider the function    \begin{eqnarray*}
    \varphi(\xi,t)\coloneqq \frac{K}{u-c_0},
\end{eqnarray*} where $c_0\coloneqq \frac{\varepsilon_0} 2$. Thus, $\varphi$ is well-defined for all $(\xi,t)\in \mathcal{C}_\theta\times[0, T^*)$.

Direct computation yields 
    \begin{eqnarray}\label{var euqation}
        \mathcal{L} \varphi &=&\frac{\mathcal{L} K}{u-c_0} -\frac{K}{(u-c_0)^2} \mathcal{L} u+ \frac{2 K\ell}{u-c_0} a^{ij} \nabla_{i}\varphi\nabla_{j} u.
    \end{eqnarray}
    Inserting Eq. \eqref{h bar evolution GCF} and \eqref{K evol GCF} into \eqref{var euqation}, we have
    \begin{eqnarray*}
        \mathcal{L} \varphi &=& \frac{ 2K a^{ij}\nabla_{i}K\nabla_{j}\ell+ K^{2} H}{u-c_0} -\frac{K}{(u-c_0)^2} \left(-(n+1)K+K H u\right)  \\&& -\frac{2K}{(u-c_0)^2} K a^{ij} \nabla_{j}u \nabla_{i}\ell + \frac{2 K \ell}{u-c_0} a^{ij} \nabla_{i} \varphi \nabla_{j} u        \\&=&  2  K a^{ij} \nabla_{i}\varphi\nabla_{j}\ell+2 \varphi \ell a^{ij} \nabla_{i}\varphi\nabla_{j} u+ \varphi^2 (n +1-c_0  H)\\&\leq & n  c_0^{1+\frac{1}{n  }}\varphi^2\left(-\varphi^{\frac{1}{n  }} +\frac{n +1}{n  c_0^{1+\frac 1 {n}}}\right),\quad \text{ mod } \nabla \varphi,
    \end{eqnarray*}where in the last inequality we have used the fact that $H\geq n K^{\frac 1 n}$ and $ u\geq 2c_0$. 
   On the other hand, in view of \eqref{robin of bar h} and \eqref{robin of K}, we have 
    \begin{eqnarray}\label{neumann-tso-fun}
        \nabla_\mu \varphi=  0,\quad \text{ on } \partial \mathcal{C}_\theta.
    \end{eqnarray}
    By the maximum principle, we have
    \begin{eqnarray*}
        \varphi \leq \max\left\{\frac{1}{c_0} \left( \frac{n +1}{ nc_0}\right)^{n}, \max_{\mathcal{C}_\theta}\varphi(\cdot, 0) \right\} .
    \end{eqnarray*}
   It follows
\begin{eqnarray}\label{K-upper-bound}
        K\leq \max\left\{\left(\frac{n+1}{n}\right)^{n}\frac{\max\limits_{\mathcal{C}_{\theta}}u(\cdot, t)}{c_{0}^{1+n}}, \frac{ \max\limits_{\mathcal{C}_{\theta}}u(\cdot, t)\cdot K_{0}}{u(\cdot,0)-c_{0}}
        \right\}.
    \end{eqnarray}
Since $\partial_t u \leq 0$ and $\nabla_\mu u =0$ on $\partial \mathcal{C}_\theta$,  we have $$u\leq  \max\limits_{\mathcal{C}_\theta} u(\cdot, 0).$$  Therefore, as long as  flow \eqref{c-Gauss curvature flow} exists and $ u\geq 2c_0$, there holds
\begin{eqnarray*}
        K   \leq  \max\limits_{\mathcal{C}_\theta} u(\cdot, 0) \cdot  \max\left \{\frac{1}{c_0} \left( \frac{n+1}{n c_0}\right)^{n}, \frac{\max\limits_{\mathcal{C}_\theta}K_0}{c_0}\right\} .
    \end{eqnarray*}Thus the statement follows.

\label{curvature est}
Let $\Sigma_t$ be the solution of the flow \eqref{c-Gauss curvature flow} on the time interval $[0, T^*)$. If $\theta\in (0,\pi/2)$ and the capillary inner radius of $\Sigma_t$ has a uniform positive lower bound $\varepsilon_0$,  then there exist positive constants $C_0$ and $C_1$ such that 
    \begin{eqnarray}\label{upper-lower-curvature est}
      C_0^{-1}\leq \kappa_i\leq  C_1 \quad \text{ for all } 1\leq i\leq n,
    \end{eqnarray} 
    where the constant $C_1$ only depends  on $n, \frac{1}{\varepsilon_0}$ and  initial data. 
    In particular,   the constant $C_0$ only depends on the initial data and $n$.

To show  \eqref{upper-lower-curvature est}, we first establish the positive lower bound of the principal curvatures. Define 
\begin{eqnarray*}
    \Phi\coloneqq  \Delta h+nh=\sum_{i=1}^n \frac{1}{\kappa_i}, 
\end{eqnarray*} which is the harmonic  curvature of $\Sigma_t$. 

First of all, we \textbf{claim} that if $\theta\in (0,\pi/2)$, there holds
\begin{eqnarray} 
\label{boundary of Phi} 
    \nabla_\mu \Phi \leq 0 \quad \text{ on } \partial \mathcal{C}_\theta.
\end{eqnarray} 
In fact, along $\partial{\mathcal C}_\theta$, we choose  an orthonormal frame $\{e_i\}_{i=1}^n$  such that $e_n=\mu$. Since  $\nabla_\mu h=\cot\theta h$ on $\partial \mathcal{C}_\theta$, then for all $1\leq \beta\leq n-1$,  
		\begin{eqnarray*}
			\nabla_\beta (h_n)=\cot\theta \nabla_\beta h,
		\end{eqnarray*} 
  together with the Gauss-Weingarten equation of $\partial \mathcal{C}_\theta \subset \mathcal{C}_\theta$,  we have
		\begin{eqnarray}\label{h_1n}
			h_{\beta n}=	\nabla^2h(e_\beta ,e_n)=\nabla_{e_\beta}(\nabla h(e_n))-\nabla h(\nabla_{e_\beta}e_n) =0.
		\end{eqnarray}
		Applying the Gauss-Weingarten equation of $\partial \mathcal{C}_\theta \subset \mathcal{C}_\theta$ again and combining with \eqref{h_1n}, we have 
		\begin{eqnarray*}
			\nabla_{\beta\beta n}h&=&(\nabla^3 h)(e_\beta,e_\beta,e_n)	=(\nabla_{e_\beta }(\nabla^2 h))(e_\beta ,e_n)\\&=& \nabla_{e_\beta}(\nabla^2 h(e_\beta,e_n))-\nabla^2 h(\nabla_{e_\beta }e_\beta,e_n)-\nabla^2 h(e_\beta,\nabla_{e_\beta}e_n)
			\\&=&\cot\theta h_{nn}-\cot\theta h_{\beta \beta}.
		\end{eqnarray*} 
		The commutator formula  on $\mathcal{C}_{\theta}$ implies  
		\begin{eqnarray*}
			\nabla_{n\beta\beta } h=\nabla_{\beta\beta n}h-h_n=\cot\theta ( h_{nn}-  h_{\beta\beta }- h),
		\end{eqnarray*} then it follows
  \begin{eqnarray}\label{a aan}
     \nabla_{n} a_{\beta\beta} =\nabla_{n}h_{\beta\beta} + h_{n}= \cot\theta (a_{nn}-a_{\beta\beta}).
  \end{eqnarray}  
   From \eqref{robin of K}, we have
    \begin{eqnarray*}
   \sum_{\beta=1}^{n-1}     a^{\beta\beta}\nabla_{n}a_{\beta\beta}+a^{nn}\nabla_{n}a_{nn}=0,
    \end{eqnarray*}that is, \begin{eqnarray*}
       \nabla_{n} a_{nn}=-   \sum_{\beta=1}^{n-1}    
 \frac{a^{\beta\beta }}{a^{nn}}\nabla_{n}a_{\beta\beta},
    \end{eqnarray*}
 which,   together with \eqref{a aan}, implies
\begin{eqnarray*}
    \nabla_\mu \Phi&=&   \sum_{\beta=1}^{n-1}\nabla_\mu a_{\beta\beta}+\nabla_\mu a_{nn}
    \\&=& \cot\theta  \sum_{\beta=1}^{n-1} \left( 1-\frac{ a^{\beta\beta}}{a^{nn}}\right) (a_{nn}-a_{\beta\beta}) \leq 0,
\end{eqnarray*}
where the last inequality follows from the positive definiteness of $(a_{ij})$ and $\theta \in(0,\pi/2)$. Hence, we prove the assertion \eqref{boundary of Phi}.


Next, we compute the evolution equation of $\Phi$, bear in mind that $$\Delta \ell+n\ell =n.$$ From Eq. \eqref{prop-scalar equ},  we derive
\begin{eqnarray*}
    \partial_t \Phi &=&\Delta (\partial_t h)+n\partial_t h
    \\&=& -\ell \Delta K-2\nabla \ell \cdot \nabla K-K\Delta \ell   -n\ell K
    \\&=&- \ell K \Delta K-2\nabla \ell\cdot \nabla K-nK,
\end{eqnarray*}
and
\begin{eqnarray}\label{eq_add1}
    \nabla_i K=-Ka^{kl}\nabla_{i}a_{kl},
\end{eqnarray}
By the covariant derivative commutator formula on $\mathcal{C}_\theta$, we have
\begin{eqnarray*}
\nabla_{j}\nabla_{i}h_{pq}=\nabla_{q}\nabla_{p}h_{ij}+2(h_{pq}\delta_{ij}-h_{ij}\delta_{pq})+h_{iq}\delta_{pj}-h_{jp}\delta_{iq},
\end{eqnarray*} which implies
\begin{eqnarray*} \nabla_{j}\nabla_{i}a_{pq}&=&\nabla_{j}\nabla_{i}h_{pq}+h_{ij}\delta_{pq}

 \\&=&\nabla_{q}\nabla_{p}a_{ij} +a_{pq}\delta_{ij}-a_{ij}\delta_{pq}+a_{iq}\delta_{pj}-a_{jp}\delta_{iq}.
\end{eqnarray*} 
Then
\begin{eqnarray*}
    \nabla_{ij} K&=& -\nabla_j K a^{kl}\nabla_{i}a_{kl}-Ka^{kl}\nabla_{j}\nabla_{i}a_{kl}-K\nabla_{j}a^{kl}\nabla_{i}a_{kl}

    \\&=&  -Ka^{kl} (\nabla_{l}\nabla_{k}a_{ij}+a_{kl}\delta_{ij}-a_{ij}\delta_{kl}+a_{il}\delta_{kj}-a_{jk}\delta_{il}) 
 \\&& +Ka^{kp} \nabla_{j}a_{pq} a^{ql}\nabla_{i}a_{kl}+ Ka^{pq}\nabla_{j}a_{pq}a^{kl}\nabla_{i}a_{kl} 
\end{eqnarray*}
and
\begin{eqnarray*}
    \Delta K&=&  Ka^{kp} \nabla_{i}a_{pq} a^{ql}\nabla_{i}a_{kl}+ Ka^{pq}\nabla_{i}a_{pq}a^{kl}\nabla_{i}a_{kl} 
    \\&& -Ka^{kl}\nabla_{l}\nabla_{k}\Phi-n^2 K+\Phi  H K.
\end{eqnarray*}
Altogether yields
\begin{eqnarray*}
    \partial_t\Phi &=&   \ell Ka^{kl}\nabla_{l}\nabla_{k}\Phi+ n^2 \ell -\ell K \Phi H -n K                     
   -2 \nabla \ell\cdot \nabla K  \\&&  -\ell K a^{kp} \nabla_{i}a_{pq} a^{ql}\nabla_{i}a_{kl}- \ell  K a^{pq}\nabla_{i}a_{pq}a^{kl}\nabla_{i}a_{kl}.
\end{eqnarray*}
From \eqref{boundary of Phi}, we  have that $\Phi$ attains its maximum value  at some interior point, say $\xi_0 \in \mathcal{C}_{\theta} \setminus \partial \mathcal{C}_{\theta}$. Assume that $a_{ij}$ is diagonal at this point, which in turn implies that $a^{ij}$ is also diagonal at $\xi_0$. Then at $\xi_0$, we find
\begin{eqnarray} \notag
    0 &\leq &\mathcal{L} \Phi=\partial_t\Phi- \ell Ka^{kl}\nabla_{k}\nabla_{l}\Phi   \notag
    \\&=& (n\ell-1) nK - \ell K \Phi H 
    \notag \\&&  -  \ell K a^{kp} \nabla_{i}a_{pq} a^{ql}\nabla_{i}a_{kl} - \ell K a^{pq}\nabla_{i}a_{pq}a^{kl}\nabla_{i}a_{kl}  -2 \nabla\ell \cdot \nabla K.\label{evo of phi}
\end{eqnarray}
From \eqref{eq_add1} we have 
\begin{eqnarray*}
   -2  \nabla \ell\cdot \nabla K=2\cos\theta \<e_i,e\> K a^{kk}\nabla_{i}a_{kk}.
\end{eqnarray*}
By using the Cauchy-Schwarz inequality and the convexity of $\Sigma_t$,  we obtain
\begin{eqnarray}
  -\ell \sum_{k,l,i} a^{kk}a^{ll}(\nabla_{i}a_{kl})^2-  \ell  \sum_i (\sum_k a^{kk}\nabla_{i}a_{kk} )^2-2\cos\theta \<e_i,e\> a^{kk} \nabla_{i}a_{kk} \leq  C  ,~~~~~~\label{Kalpha upper}
\end{eqnarray} 
where the constant $C$ only depends on $n$.
  Inserting \eqref{Kalpha upper} into  \eqref{evo of phi}, and using the fact that $H\geq nK^{1/n}$ , we derive that
\begin{eqnarray*}
     \ell K^{\frac{1}{n}} \Phi\leq \frac{1}{n} \ell H\Phi \le ( n \ell -1)+C,
\end{eqnarray*}
which, together with  Proposition \ref{lower bound of K}, gives 
\begin{eqnarray*}
  \Phi \leq C_{0},
\end{eqnarray*}for some positive constant $C_{0}$ depending on $n$ and $\Sigma_{0}$. It implies  \begin{eqnarray}\label{kappa-lower-bound}
    \kappa_i\geq C^{-1}_{0}.
\end{eqnarray}
The upper bound of $\kappa_i$ follows directly from \eqref{kappa-lower-bound} and Proposition \ref{upper bound of K}, since
\begin{eqnarray*}
    \kappa_i = K \prod_{j\neq i} \kappa_j^{-1} \leq C C_0^{-(n-1)} \coloneqq C_1.
\end{eqnarray*}
This completes the proof.

From \cite[Theorem 1.1 for $k=0$]{WWX22},   we have
    \begin{eqnarray*}
        \frac{d}{dt}{\rm{Vol}}(\widehat {\Sigma}_{t})&=&\int_{\Sigma_{t}}hd\mu_{t} - \int_{\Sigma_t} K(\cdot,t ) (1+\cos\theta\<\nu, e\>)d\mu_{t}\\
        &=&(n+1) \left( {\rm{Vol}}(\widehat\Sigma_t )-{\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})\right),
    \end{eqnarray*}
where $d\mu_{t}$ is the area element of $\Sigma_{t}$. Together with the assumption that ${\rm{Vol}}(\widehat\Sigma_0 )={\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$, we derive that  ${\rm{Vol}}(\widehat\Sigma_t)={\rm{Vol}}(\widehat{\mathcal{C}_\theta})$  for all $t\geq 0$. Therefore, the conclusion follows.

\label{GCF-normal to soliton}
Let $\Sigma_0$ be a strictly convex capillary hypersurface in $\overline{\mathbb{R}^{n+1}_+}$ and $\theta\in(0,\pi/2)$, then flow \eqref{GCF-capillary-normalized} has a smooth solution $\Sigma_t\coloneqq X(\cdot,t)$, which is strictly convex capillary hypersurface for all $t\in[0,+\infty)$. Moreover,  the solution of flow \eqref{GCF-capillary-normalized} converges to a smooth, strictly convex capillary hypersurface $\Sigma_\infty\subset \overline{\mathbb{R}^{n+1}_+}$ as  $t\to +\infty$.                                                                                                        
Furthermore, $\Sigma_\infty$ satisfies 
\begin{eqnarray}\label{eq-soliton-normalized-GCF}
\left\{
\begin{array}{llll}
	K &=& \frac{\<X,\nu\> } {1+\cos\theta\<\nu, e\>} & \text{ in } \Sigma_\infty,\\ 
	\<\nu,e\>&=& -\cos\theta & \text{ on } \partial \Sigma_\infty.\end{array}
\right.
\end{eqnarray}

\label{def-cap-entropy}
Let $\widehat\Sigma\in \mathcal{K}_\theta$ be a capillary convex body. The capillary entropy functional $\mathcal{E}_{\theta}$ associated with $\widehat\Sigma$ is defined by 
\begin{eqnarray*}
    \mathcal{E}_{\theta}(\widehat\Sigma)\coloneqq \sup_{z\in {\rm{int}}(\widehat{\partial\Sigma})}    \mathcal{E}_{\theta}(\widehat\Sigma,z),
\end{eqnarray*} where
\begin{eqnarray*}
    \mathcal{E}_{\theta}(\widehat\Sigma,z)\coloneqq 
        \frac 1 {\omega_\theta}\int_{\mathcal{C}_\theta} \left(\log u_{z}(\xi)\right) \ell(\xi)  d\sigma,
\end{eqnarray*}
and  $\omega_\theta\coloneqq |\mathcal{C}_\theta|-\cos\theta |\widehat{\partial\mathcal{C}_\theta}|$ is the capillary area of $\mathcal{C}_\theta$.

\label{lem-low-entroy}
 Let $\widehat\Sigma\in \mathcal{K}_\theta$ with  $\theta\in(0, \pi/2)$ and  ${\rm{Vol}}(\widehat \Sigma) ={\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$. If $z_s \in \widehat{\partial \Sigma} $
    is the capillary Santal\'o point of $\widehat{\Sigma}$, 
   then
    \begin{eqnarray}\label{lower bdd}
        \frac 1 {\omega_\theta}\int_{\mathcal{C}_\theta} \left(\log u_{z_s}(\xi)\right) \ell(\xi) d\sigma \ge -C,
        \end{eqnarray}
   where the constant $C > 0$ only depends on $n$ and $\theta$.

The proof follows closely the idea of Guan-Ni \cite[Proposition~1.1]{GN}, by adjusting to use Proposition \ref{prop-volume-polar-body} and Proposition \ref{prop-santalo-ineq}. 

    From  Proposition \ref{prop-volume-polar-body}, 
\begin{eqnarray*}
{\rm{Vol}}(\widehat{\Sigma}^*_{z_s}) 
&=&\frac{1}{n+1}\int_{\mathcal{C}_{\theta}}\frac{\ell(\xi)}{u^{n+1}_{z_{s}}(\xi)} d\sigma.
 \end{eqnarray*}
By applying Jensen's inequality, we deduce that
\begin{eqnarray}\label{Jen-ine}
 \exp \left(   \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\log \left(\frac{1}{u^{n+1}_{z_{s}}(\xi)} \right)\ell(\xi) d\sigma\right)\leq \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\frac{1}{u^{n+1}_{z_{s}}(\xi)}\ell(\xi) d\sigma=\frac{n+1}{\omega_\theta} {\rm{Vol}}(\widehat{\Sigma}_{z_s}^{\ast}).
\end{eqnarray}
Inserting the simple fact that $\omega_{\theta}=(n+1){\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$ into \eqref{Jen-ine}, and together with Proposition \ref{prop-santalo-ineq},  we obtain
\begin{eqnarray*}
   \exp \left(-\frac{(n+1)}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}} \left(\log u_{z_{s}}(\xi)\right)\ell(\xi) d\sigma  \right)
   \leq \frac{{\rm{Vol}}(\widehat{\Sigma}_{z_s}^{\ast})}{{\rm{Vol}}(\widehat\mathcal{C}_\theta)}\leq \frac{1}{2}\left(\frac{{\rm{Vol}}(\mathbb{B}^{n+1})}{{\rm{Vol}(\widehat\mathcal{C}_{\theta})}}\right)^{2},
\end{eqnarray*}
then this implies \eqref{lower bdd}.

\label{prop-exist-cap-entropy-point}
 Let $\widehat\Sigma\in \mathcal{K}_\theta$ with  $\theta\in(0, \pi/2)$. Then there exists a unique point $z_{e}\in \widehat{\partial \Sigma} $ such that $$\mathcal{E}_{\theta}(\widehat{\Sigma})=\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}
\left(\log u_{z_{e}}(\xi)\right)\ell(\xi) d\sigma.$$

We divide the proof into two steps: first, we establish the existence of $z_e$, second, we prove its uniqueness.

\


 \textit{Step 1: Existence}. By Definition \ref{def-cap-entropy}, we know there exists a  sequence $\{z_j\}_{j\geq 1}\subset \text{int}(\widehat{\partial\Sigma})$ and some point $z_e\in \widehat{\partial\Sigma}$  such that 
\begin{eqnarray}\label{maximizing-sequence-entropy}
    \mathcal{E}_{\theta}(\widehat{\Sigma}, z_j)\rightarrow \mathcal{E}_{\theta}(\widehat{\Sigma})~ ~~{\rm{and}}~z_j\rightarrow z_{e}~~{\rm{as}}~j\rightarrow +\infty.
\end{eqnarray}
From \eqref{capillary support}, \eqref{defn-capillary-outer-radius} and \cite[Remark 2.8]{MWW}, we know  
\begin{eqnarray}\label{double-control}
    u_{z_j}(\xi)\leq 2\rho_{+}(\widehat{\Sigma}, \theta), ~~\text{ for all } \xi\in \mathcal{C}_\theta, \end{eqnarray}
by Fatou's Lemma and \eqref{maximizing-sequence-entropy}, we deduce 
\begin{eqnarray*}
 \int_{\mathcal{C}_{\theta}}\log \left(\frac{2\rho_{+}(\widehat{\Sigma}, \theta)}{u_{z_{e}}(\xi)}\right)\ell (\xi) d\sigma\leq \liminf\limits_{j\rightarrow+\infty} \int_{\mathcal{C}_{\theta}}\log \left(\frac{2\rho_{+}(\widehat{\Sigma
    }, \theta)}{u_{z_j}(\xi)}\right)\ell(\xi)d\sigma,
\end{eqnarray*}
in view of \eqref{maximizing-sequence-entropy}, then it follows
\begin{eqnarray}\label{fatou-lemma-estimate}
    \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}} \left(\log u_{z_{e}}(\xi)\right)\ell(\xi)d\sigma\geq \limsup\limits_{j\rightarrow +\infty} \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}(\log u_{z_j}(\xi))\ell(\xi)d\sigma=\mathcal{E}_{\theta}(\widehat{\Sigma}).
\end{eqnarray}
On the other hand, by Definition \ref{def-cap-entropy}, it is obvious that
$$ \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u_{z_{e}}(\xi)\right)\ell(\xi)d\sigma\leq \mathcal{E}_{\theta}(\widehat{\Sigma}),$$
together with \eqref{fatou-lemma-estimate}, we obtain that $z_e$ is the desired supremum point of $\mathcal{E}_\theta(\widehat\Sigma)$.

\ 

 \textit{Step 2: Uniqueness}. Without loss of generality, we assume that the origin lies in ${\rm{int}}(\widehat{\partial \Sigma})$. For all point $z\coloneqq (z_{1}, \cdots, z_{n}, 0)\in \widehat{\partial \Sigma}$, it follows from \eqref{uz} that we can rewrite
    \begin{eqnarray*}
        \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}(\log u_{z}(\xi) )\ell(\xi) d\sigma 
        &= &\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\log \left(u(\xi)-\ell^{-1}(\xi)\sum\limits_{i=1}^{n}z_{i}\xi_{i}\right)\ell(\xi) d\sigma \\&\eqqcolon & F(z),
    \end{eqnarray*}where $u(\xi)$ is the capillary support function of $\widehat\Sigma$ with respect to the origin.
A direct calculation yields
\begin{eqnarray}\label{eq-concavity-F(z)}
    \frac{\partial^{2}F(z)}{\partial z_{i}\partial z_{j}}=-\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\frac{\xi_{i}\xi_{j}}{\ell(\xi)u_{z}^{2}(\xi)}d\sigma,~~~~\text{for all}~~ 1\leq i,j\leq n.
\end{eqnarray}
Hence, this implies that $F(z)$ is strictly concave with respect to $z\in \widehat{\partial\Sigma}$, which in turn yields the uniqueness of $z_e$.

\label{lem entropy}
 Let $\widehat\Sigma\in \mathcal{K}_\theta$ with  $\theta\in(0, \pi/2)$. 
Then $\mathcal{E}_{\theta}(\widehat{\Sigma})$ is attained by a unique capillary support function $u_{z_e}$ with respect to the point $z_{e}\in \rm{int}(\widehat{\partial \Sigma})$. Moreover, $u_{z_e}$ satisfies
\begin{eqnarray}\label{ortho}
    \int_{\mathcal{C}_{\theta}}\frac { \xi_i}{u_{z_e}(\xi)} d\sigma=0,\quad \forall~ i=1,\cdots, n.
    \end{eqnarray}
    Moreover, for any capillary support function $U\neq u_{z_e}$ in $\mathcal{C}_\theta$, there holds
    \begin{eqnarray}\label{ineq-entropy-unique-support-function}
        \mathcal{E}_\theta(\widehat\Sigma) > \frac{1}{\omega_\theta} \int_{\mathcal{C}_\theta}  \left(\log U (\xi) \right) \ell d\sigma.
    \end{eqnarray}

We begin by showing that the capillary entropy point $z_{e}$ lies in ${\rm{int}}(\widehat{\partial \Sigma})$. Suppose, to the contrary, that $z_{e} \in \partial \Sigma$. Without loss of generality, we may assume that $z_{e}$ is the origin.  Following the proof and notations introduced in Proposition~\ref{pro-santalo}, for all $t \in (0, t_0)$, the point $z_{t} \coloneqq -t \zeta$ lies in ${\rm{int}}(\widehat{\partial \Sigma})$ and satisfies $u_{z_t}(\xi) > 0$. By \eqref{big}, we obtain
\begin{eqnarray*}
   0&\geq & \frac{d}{dt}\left(\int_{\mathcal{C}_{\theta}} \left(\log u_{z_t}(\xi)\right)\ell (\xi)d\sigma\right)\Big|_{t=0}=\int_{\mathcal{C}_{\theta}}\frac{\xi_{1}}{u_{z_e}(\xi)}d\sigma\\
   &=&\int_{\{\xi_{1}>0\}}
    \frac{ \xi_{1}}{u_{z_e}(\xi)}d\sigma+\int_{\{\xi_{1}<0\}}\frac{ \xi_{1}}{u_{z_e}(\xi)}d\sigma\\
    &=&\int_{\{\xi_{1}>0\}}\left(\frac{ \xi_{1}}{u_{z_e}(\xi)}-\frac{ \xi_{1} }{u_{z_e}(N(\xi))}\right)d\sigma>0,
\end{eqnarray*}
which leads to a contradiction. Hence we derive that  $z_{e}\in {\rm{int}}(\widehat{\partial \Sigma})$ and in turn $u_{z_e}(\xi)>0$ for all $\xi\in \mathcal{C}_\theta$.  

Next, we verify that the assertion \eqref{ortho} holds. For all $1 \leq i \leq n$, denote $z_e^{r,i} \coloneqq z_{e} - r E_{i}$. For sufficiently small $r_0 > 0$, we have 
$$z_e^{r,i} \in {\rm{int}}(\widehat{\partial\Sigma}) ~~~~\text{ for all } |r| \leq r_0 ~~\text{ and }~~ 1\leq i\leq n.$$
We reformulate
    \begin{eqnarray*}
   \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u_{z_{e}^{r,i}}(\xi) \right)\ell(\xi) d\sigma=\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\log \left(u_{z_{e}}(\xi)+\ell^{-1}(\xi)r \xi_{i}\right)\ell(\xi) d\sigma\eqqcolon G_i(r).
    \end{eqnarray*}
  Proposition \ref{prop-exist-cap-entropy-point} implies that $G_i(r)$ attains its maximum value at $r=0$, hence,          
  \begin{eqnarray*}
    0=\frac{d}{dr}G_i\Big|_{r=0}=\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\frac{\xi_{i}}{u_{z_{e}}(\xi)}d\sigma.
    \end{eqnarray*}

The last assertion \eqref{ineq-entropy-unique-support-function} follows from the strict concavity of  $F(z)$ in the proof of Proposition \ref{prop-exist-cap-entropy-point}, see \eqref{eq-concavity-F(z)}.  Hence, we complete the proof.

\label{radius}
Let $\widehat{\Sigma} \in \mathcal{K}_\theta$ with $\theta\in (0, \pi /2)$. Then there exists a positive constant $C$, depending only on $n$ and $\theta$, such that
     \begin{eqnarray}\label{capillary outer}
           \rho_{+}(\widehat{\Sigma}, \theta)\leq C e^{\mathcal{E}_{\theta}(\widehat\Sigma)},
     \end{eqnarray}
     and 
     \begin{eqnarray}\label{capillary inner}
         \rho_{-}(\widehat{\Sigma}, \theta)\geq C^{-1}{\rm{Vol}}(\widehat{\Sigma}) e^{-n \mathcal{E}_{\theta}(\widehat \Sigma)}.
     \end{eqnarray}

Let $\widehat{\mathcal{C}_{\rho_{0}, \theta}(x_{0})}$ be the smallest spherical cap containing $\widehat{\Sigma}$, with radius $\rho_{0} \coloneqq \rho_{+}(\widehat{\Sigma}, \theta)$. Let $z \in \Sigma \cap \mathcal{C}_{\rho_{0}, \theta}(x_{0})$. Without loss of generality, assume $x_{0}$ is the origin, and denote $z\coloneqq (z_{1}, 0, \cdots, 0, z_{n+1})$ with $z_{1}>0$ and $ z_{n+1}\geq 0$. Moreover, we have  \begin{eqnarray}\label{z-norm}
      |z|\geq (1-\cos\theta )\rho_{+}(\widehat{\Sigma}, \theta).
  \end{eqnarray}
We begin by proving the assertion \eqref{capillary outer}. The proof is divided into two cases.

\

\noindent {\it Case 1}. $z_{1}>\frac{1}{2}|z|$. Denote $\widehat{z}\coloneqq(z_{1}, 0, \cdots, 0, 0)$. Since $\theta\in (0, \pi /2)$, we have
 line segment $$
   L_{1}\coloneqq  \left\{s\widehat{z} \mid 0\leq s\leq 1 \right\}$$ lies inside $\widehat{\partial\Sigma}$, this implies that  the support function of the  line segment $L_{1}$ with respect to the point $\frac{\widehat{z}}{2}$ is bounded above by $h_{\frac{\widehat z}{2}}$, i.e., 
\begin{eqnarray*}
      \frac{1}{2}|\<\xi, \widehat{z}\>|=\frac{1}{2}|\<\xi-\cos\theta e, \widehat{z}\>|\leq h_{\frac{\widehat z}{2}}(\xi), \quad \forall~\xi\in \mathcal{C}_{\theta}.
    \end{eqnarray*}
It yields
    \begin{eqnarray}
   &&\log z_{1} \int_{\mathcal{C}_{\theta}}\ell(\xi) d\sigma-\int_{\mathcal{C}_{\theta}}(\log 2\ell(\xi)) \ell(\xi) d\sigma+\int_{\mathcal{C}_{\theta}}\log |\xi_{1}|\ell(\xi) d\sigma\notag  \\
   &=&  \int_{\mathcal{C}_{\theta}}\log\left(\frac{1}{2\ell}|\<\xi, \widehat z\>|\right)\ell(\xi) d\sigma
   \leq \int_{\mathcal{C}_{\theta}} \left(\log u_{\frac{\widehat z}{2}}(\xi)\right)
 \ell(\xi) d\sigma \leq \omega_{\theta}\mathcal{E}_{\theta}(\widehat{\Sigma}). ~~~~~~~~\label{case-1}  \end{eqnarray}
 From \eqref{z-norm}, we have
 \begin{eqnarray*}
     \rho_+(\widehat\Sigma,\theta) \leq \frac{2 }{1-\cos\theta} z_1,
 \end{eqnarray*}
together with \eqref{case-1}, we conclude  that
\begin{eqnarray*}
    \rho_{+}(\widehat\Sigma, \theta)\leq C_1 e^{\mathcal{E}_{\theta}(\widehat{\Sigma})},
\end{eqnarray*}
where $C_1$ is a positive constant depending only on $n$ and $\theta$.

\

\noindent {\it Case 2}. $z_{1}\leq \frac{1}{2}|z|$. In this case, we have \begin{eqnarray}\label{big-1}
    z_{n+1}\geq \frac{\sqrt{3}}{2}|z|,
\end{eqnarray}
and the line segment 
$$L_{2}\coloneqq  \left\{s\widehat{z}+(1-s)z\mid  0\leq s\leq 1\right \}$$
 lies inside $\widehat\Sigma$. Similarly, the support function of the line segment $L_{2}$ with respect to the point $\widehat{z}$ is bounded above by the support function $h_{\widehat{z}}$ of $\widehat{\Sigma}$ with respect to $\widehat z$, i.e., 
\begin{eqnarray*}
z_{n+1}(\xi_{n+1}+\cos\theta) \leq h_{\widehat z}(\xi),\quad \forall~\xi\in\mathcal{C}_{\theta}.
\end{eqnarray*}
Then we get
\begin{eqnarray*}
   &&\log z_{n+1}\int_{\mathcal{C}_{\theta}}\ell(\xi) d\sigma +\int_{\mathcal{C}_{\theta}}\log (\xi_{n+1}+\cos\theta)\ell(\xi) d\sigma-\int_{\mathcal{C}_{\theta}} \log \ell(\xi) \ell(\xi) d\sigma\notag  \\
   &&\leq \int_{\mathcal{C}_{\theta}} \left(\log u_{\widehat{z}}(\xi)\right)\ell(\xi) d\sigma\leq \omega_{\theta}\mathcal{E}_{\theta}(\widehat{\Sigma}),                
\end{eqnarray*}
which implies 
\begin{eqnarray}\label{zn+1 upper}
    z_{n+1}\leq C_2 e^{\mathcal{E}_{\theta}(\widehat{\Sigma})}.
\end{eqnarray}
where $C_2$ is a positive constant depending only on $n$ and $\theta$.
Combining with \eqref{z-norm}, \eqref{big-1} and \eqref{zn+1 upper}, we also obtain \eqref{capillary outer}. Hence, we complete the proof of \eqref{capillary outer}.

Next, we proceed to show \eqref{capillary inner} with the help of \eqref{capillary outer}.  Recall that in Proposition \ref{prop-santalo-ineq}, we obtain a symmetric convex body $\Omega$ by reflecting $\widehat{\Sigma}$ with respect to the hyperplane $\{x_{n+1}=0\}$, and $\Omega$ satisfies
\begin{eqnarray}\label{double}
    2{\rm{Vol}}(\widehat{\Sigma})={\rm{Vol}}(\Omega). 
\end{eqnarray}
Together with \eqref{inner radius} and \eqref{outer radius}, we have
\begin{eqnarray}\label{volume-control}
{\rm{Vol}}(\Omega)&\leq& 2n \omega_{n-1} \left(\rho_{+}(\widehat{\Sigma})\right)^{n}\rho_{-}(\widehat{\Sigma})\notag \\
&\leq& 2n\omega_{n-1}\left(\sin \theta \rho_{+}(\widehat{\Sigma}, \theta) \right)^{n}\sin\theta \rho_{-}(\widehat{\Sigma}, \theta),
\end{eqnarray}
where $\omega_{n-1}$ is the area of $\mathbb{S}^{n-1}$. 
Inserting \eqref{capillary outer} and \eqref{double} into \eqref{volume-control}, we conclude that \eqref{capillary inner} holds.

Let $\widehat\Sigma\in \mathcal{K}_\theta$ with  $\theta\in(0, \pi/2)$  . Then there exists a positive constant $D$ depending only on $n$ and $\theta$, such that 
    \begin{eqnarray}\label{stability-estimate-entropy-point}
        \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u_{z}(\xi)\right)\ell(\xi) d\sigma \leq \mathcal{E}_{\theta}(\widehat{\Sigma})-De^{-2\mathcal{E}_{\theta}(\widehat{\Sigma})}|z-z_{e}|^{2},~\forall z\in {\rm{int}}(\widehat{\partial\Sigma}),
    \end{eqnarray}
  where $z_{e}$ is the capillary entropy point of $\widehat\Sigma$, as established in Proposition \ref{prop-exist-cap-entropy-point}.

Proposition \ref{lem entropy} ensures that $z_{e}\in {\rm{int}}(\widehat{\partial\Sigma})$.                                                                       
For all $z\in {\rm{int}}(\widehat{\partial\Sigma})$,  the strict convexity of $\widehat{\partial\Sigma}$ implies the line segment 
  $$N\coloneqq  \left\{s z_{e}+(1-s)z \mid  0\leq s\leq 1 \right\} $$  lies in ${\rm{int}}({\widehat{\partial\Sigma}})$.                                             
 Denote $t=z-z_{e}\eqqcolon (t_{1}, \cdots, t_{n}, 0)$. By \eqref{capillary support}, we rewrite
  \begin{eqnarray*}
      \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u_{z}(\xi)\right)\ell(\xi) d\sigma
      =\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\log \left(u_{z_{e}}(\xi)-\ell^{-1} \sum_{i=1}^n t_{i}\xi_{i}\right)\ell(\xi) d\sigma\eqqcolon Q(t).
  \end{eqnarray*}
  By direct calculations, together with \eqref{ortho}, it follows
  \begin{eqnarray*}
      \frac{\partial Q(t)}{\partial t_{i}}\Big|_{t=0}=-\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\frac{\xi_{i}}{u_{z_e}(\xi)}d\sigma=0,~~ \text{ for all } \quad 1\leq i\leq n,
  \end{eqnarray*}
and  
\begin{eqnarray*}
    \frac{\partial^{2}Q(t)}{\partial t_{i} \partial t_{j}}=-\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\frac{\xi_{i}\xi_{j}}{\ell(\xi) u_{z}^{2}(\xi)}d\sigma, ~~\text{ for all } \quad 1\leq i,j \leq n, 
\end{eqnarray*} 
together with Taylor's theorem, it follows that there exists a point $z_*\in{\rm{int}}(\widehat{\partial\Sigma})$, such that
\begin{eqnarray}\label{Qt}
    Q(t)=Q(0)-\frac{1}{2\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\frac{\<\xi, z-z_{e}\>^{2}}{\ell u_{z_*}^{2}(\xi)}d\sigma.
\end{eqnarray}
Using \eqref{double-control} and \eqref{capillary outer}, we get
\begin{eqnarray}\label{support-lower}
    \frac{1}{u_{z_*}(\xi)}\geq \frac{1}{2\rho_{+}(\widehat{\Sigma}, \theta)}\geq \frac{1}{2C}e^{-\mathcal{E}_{\theta}(\widehat{\Sigma})}.
\end{eqnarray}
Inserting \eqref{support-lower} into \eqref{Qt}, we obtain 
\begin{eqnarray*}
    Q(t)&\leq &Q(0)-\frac{1}{4C^{2}}e^{-2\mathcal{E}_{\theta}(\widehat{\Sigma})}|z-z_{e}|^{2}\int_{\mathcal{C}_{\theta}}\left<\xi, \frac{z-z_{e}}{|z-z_{e}|}\right>^{2}\ell^{-1}(\xi)d\sigma \\
    &\leq& \mathcal{E}_{\theta}(\widehat{\Sigma})-De^{-2\mathcal{E}_{\theta}(\widehat{\Sigma})}|z-z_{e}|^{2},
    \end{eqnarray*}
where the constant $D$ only depends on $n$ and $\theta$. Hence, we complete the proof.

For any $t_{0}>0$, 
   let $u_{e(t_{0})}$ be the capillary support function of $\widehat\Sigma_{t_0} $ with respect to the capillary entropy point $e({t_{0}})\in  \text{int}(\widehat{\partial\Sigma}_{t_{0}})$.                                                          
   We define the function
   $$U(\xi,t)\coloneqq u(\xi,t)-e^{t-t_{0}}\frac{\<e(t_{0}), \xi\>}{\ell(\xi)}, ~~~\xi\in \mathcal{C}_\theta, ~~t\geq 0.$$
 By the very definition, we note that \begin{eqnarray}\label{eq-U-t-0}
  U(\xi,t_0)=u_{e(t_0)}(\xi), \text{ for all } \xi\in \mathcal{C}_\theta.
  \end{eqnarray} Hence $U(\cdot,t)>0$ in $\mathcal{C}_\theta$ for all $t\in(t_0-\varepsilon, t_0]$, where $\varepsilon>0$ is  some sufficiently small constant.
   Moreover, it is readily seen that $U(\cdot, t)$ satisfies $\nabla^2(\ell U)+(\ell U) I>0$ in $\mathcal{C}_\theta$ and $\nabla_\mu (\ell U)=\cot\theta \ell U$ on $\partial\mathcal{C}_\theta$, then $U$ is the capillary support function by using \cite[Definition 2.5 and Proposition 2.6]{MWWX}. Thus, by applying \eqref{ineq-entropy-unique-support-function} to $\widehat\Sigma_t$, we obtain
   \begin{eqnarray}\label{ineq-entropy-unique-support-fuction-flow}
       \mathcal{E}_\theta(\widehat\Sigma_t) \geq  \frac 1 {\omega_\theta} \int_{\mathcal{C}_\theta} \left(\log U(\xi,t) \right)\ell d\sigma, ~~~~~\text{ for all } t\in (t_0-\varepsilon, t_0].
   \end{eqnarray}
   On the other hand, it follows from \eqref{eq-scalar-capillary-support-normalized-GCF} that $U(\cdot,t)$ satisfies
   \begin{eqnarray}\label{equation-U-flow} \left\{
\begin{array}{llll}
  \partial_t U &=&U - K(\xi,t)   & \text{ in } ~\mathcal{C}_\theta ,\\ 
	\nabla_\mu U&=& 0 & \text{ on }~ \partial \mathcal{C}_\theta ,\end{array}  \right.
\end{eqnarray}where we recall that $K(\xi,t)=\frac 1 {\det \left(\nabla^2 h+h \sigma \right)}=\frac 1 {\det \left(\nabla^2 (\ell U)+\ell U \sigma \right)}.$

A direct calculation and using \eqref{equation-U-flow}, it follows     \begin{eqnarray}\label{d-1}
        \frac{d}{dt} \int_{\mathcal{C}_{\theta}}(\log U(\xi,t))\ell(\xi) d\sigma = \int_{\mathcal{C}_{\theta}}\frac{U(\xi,t)-K(\xi, t)}{U(\xi,t)}\ell(\xi) d\sigma.
    \end{eqnarray}
Note that
\begin{eqnarray}
    && \int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{U(\xi,t)}{K(\xi, t)}}-\sqrt{\frac{K(\xi, t)}{U(\xi,t)}}\right)^{2}\ell (\xi)d\sigma \notag \\
    &=& \int_{\mathcal{C}_{\theta}}\left(\frac{K(\xi, t)}{U(\xi,t)}+\frac{U(\xi,t)}{K(\xi, t)}-2\right)\ell(\xi) d\sigma \notag \\
    &=& \int_{\mathcal{C}_{\theta}}\frac{K(\xi, t)}{U(\xi,t)}\ell(\xi) d\sigma+ \int_{\mathcal{C}_\theta}  \frac{h(\xi,t)-e^{t-t_0}\<e(t_0),\xi\>}{K(\xi,t)} d\sigma-2\int_{\mathcal{C}_{\theta}}\ell(\xi) d\sigma. \label{eq-square-form-Sigma-t}  
\end{eqnarray}
Next, we analyze the middle integral term. From \cite[Proposition 2.12 and its proof]{MWWX} and Proposition \ref{volume-preserving}, we have
\begin{eqnarray}
    \int_{\mathcal{C}_\theta} \frac {h(\xi,t)}{K(\xi,t)} d\sigma &= & \int_{\mathcal{C}_\theta}  h \det(\nabla^2 h+h\sigma) d\sigma = (n+1)\text{Vol}(\widehat\Sigma_t) \notag\\&=&(n+1)\text{Vol}(\widehat\mathcal{C}_\theta)
    =\int_{\mathcal{C}_\theta}\ell d\sigma. \label{eq-area-formula-Sigma-t}
\end{eqnarray}
By divergence theorem on $\widehat\Sigma_t$, there holds
\begin{eqnarray}
\int_{\mathcal{C}_\theta} \frac{\<e(t_0), \xi\>}{K(\xi,t)} d\sigma &= & \int_{\mathcal{C}_\theta} \frac{\<e(t_0), \xi-\cos\theta e\>}{K(\xi,t)} d\sigma = \int_{\Sigma_t} \< e(t_0), \nu(\cdot,t)\> d\mu_t  \notag \\&=&\int_{\widehat\Sigma_t} \text{div}_{\mathbb{R}^{n+1}_+} \left( e(t_0)\right) dV=0   
    .\label{eq-divergence-thm-Sigma-t}
\end{eqnarray}
Inserting \eqref{eq-area-formula-Sigma-t} and \eqref{eq-divergence-thm-Sigma-t} into \eqref{eq-square-form-Sigma-t}, we obtain
\begin{eqnarray*}
\int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{U(\xi,t)}{K(\xi, t)}}-\sqrt{\frac{K(\xi, t)}{U(\xi,t)}}\right)^{2}\ell (\xi)d\sigma =-\int_{\mathcal{C}_\theta} \left(1-\frac{K(\xi,t)}{U(\xi,t)}  \right) \ell d\sigma,
\end{eqnarray*}


together with \eqref{d-1}, we derive 
\begin{eqnarray*}
\frac{d}{dt} \int_{\mathcal{C}_{\theta}}(\log U(\xi,t))\ell(\xi) d\sigma =- \int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{U(\xi,t)}{K(\xi, t)}}-\sqrt{\frac{K(\xi, t)}{U(\xi,t)}}\right)^{2}\ell (\xi)d\sigma\leq 0,
\end{eqnarray*}
    which holds for all $t\in(t-\varepsilon, t_0]$. In view of \eqref{eq-U-t-0}, it yields
    \begin{eqnarray*}
        \int_{\mathcal{C}_\theta} \left(\log U(\xi,t) \right)\ell (\xi)d\sigma \geq \int_{\mathcal{C}_\theta} \left(\log U(\xi,t_0)\right)\ell (\xi)d\sigma =\omega_\theta \mathcal{E}_\theta(\widehat\Sigma_{t_0}),
    \end{eqnarray*} together with \eqref{ineq-entropy-unique-support-fuction-flow}, we obtain
    \begin{eqnarray*}
        \mathcal{E}_{\theta}(\widehat\Sigma_t )\geq \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log U(\xi,t)\right)\ell(\xi)d\sigma\geq \mathcal{E}_{\theta}(\widehat\Sigma_{t_0} ),
        \end{eqnarray*}holds for all $t\in(t-\varepsilon, t_0]$. Therefore, the conclusion holds due to the arbitrariness of $t_0>0$.

\label{pro-limit}
Suppose $u(\xi, t)$ is the positive solution to flow \eqref{eq-scalar-capillary-support-normalized-GCF}, then for all $t\geq 0$, there holds
    \begin{eqnarray}\label{limit prop}
       \int_{\mathcal{C}_{\theta}}\left(\log u(\xi,t)\right)\ell(\xi) d\sigma\geq \omega_\theta\mathcal{E}_{\infty}+\int_{t}^{+\infty}\int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{K(\xi, t)}{u(\xi,t)}}-\sqrt{\frac{u(\xi, t)}{K(\xi, t)}}\right)^{2} \ell(\xi) d\sigma dt.
    \end{eqnarray}

Fix $T_{1}>0$ and choose $T>T_{1}$. Let $a^{T}=(a_{1}^{T}, \cdots, a_{n}^{T}, 0)\eqqcolon e(T) \in \text{int}(\widehat{\partial\Sigma}_T)$ be the capillary entropy point of $\widehat\Sigma_T $. Consider the function
\begin{eqnarray*}
    u^{T}(\xi, t)\coloneqq u(\xi, t)-e^{(t-T)}\ell^{-1} (\xi)\sum\limits_{i=1}^{n}a_{i}^{T}\xi_{i},~~~~\xi\in\mathcal{C}_\theta,~~ t\geq 0.
\end{eqnarray*} It is obvious that  \begin{eqnarray}\label{eq-rewrite-u-T-at-time-T}
    u^T(\xi, T)=u_{e(T)}(\xi,T),~~\forall \xi\in \mathcal{C}_\theta,
\end{eqnarray} is exactly the capillary support function of $\widehat\Sigma_T$ with respect to $e(T)$. Moreover, it follows from \eqref{eq-scalar-capillary-support-normalized-GCF} that $u^{T}(\cdot,t)$ satisfies
   \begin{eqnarray}\label{uT equ} \left\{
\begin{array}{llll}
  \partial_t u^{T} &=&u^{T}-\frac{1}{\det \left(\nabla^2 (\ell u^{T})+\ell u^{T} \sigma \right)}   & \text{ in } ~\mathcal{C}_\theta ,\\ 
	\nabla_\mu u^{T}&=& 0 & \text{ on }~ \partial \mathcal{C}_\theta  .\end{array}  \right.
\end{eqnarray}
Proposition \ref{prop-mono} implies
\begin{eqnarray}\label{entropy upper}
    \mathcal{E}_{\theta}(\widehat\Sigma_t )\leq \mathcal{E}_{\theta}(\widehat\Sigma_0 ), \quad\quad {\rm{for~all}}~t\in [0,+\infty),
    \end{eqnarray}
together with Proposition \ref{radius}, it yields
\begin{eqnarray}\label{aT}
    |a^{T}|\leq C,
\end{eqnarray} where $C>0$ only depends on $n$ and $\Sigma_0$. 
Let $T$ be sufficiently large such that $u^{T}(\xi, 0) > 0$ for all $\xi\in \mathcal{C}_\theta$.  From \eqref{eq-rewrite-u-T-at-time-T} and Proposition \ref{lem entropy}, we have  \begin{eqnarray}\label{uT}
    u^{T}(\xi, T)>0, \quad\quad {\rm{for~all}}~\xi\in \mathcal{C}_{\theta}.
\end{eqnarray} 
Next, we \textbf{claim:} $$u^{T}(\xi, t)>0, ~~\text{for~ all}~(\xi,t)\in  \mathcal{C}_{\theta}\times[0, T].$$ 
We argue by contradiction. Suppose the claim is false, then there exists a point $\xi_{0}\in \mathcal{C}_{\theta}$ and $t_0\in (0, T)$ such that $u^{T}(\xi_{0}, t_{0})= 0$.                                                                                                             
By the first equation in \eqref{uT equ},  we have $\partial_{t}u^{T}(\xi_{0}, t_{0})<0$, then there exists a small constant $\delta>0$ and for all $t\in (t_{0}, t_{0}+\delta]$, we have $u^{T}(\xi_{0}, t)<0$. Repeating the same process at $t=t_0+\delta$, we iterative deduce that $u^{T}(\xi_{0}, T)<0$, which contradicts  with \eqref{uT}. Hence, the claim is true. 

Following the similar argument as in the proof of Proposition \ref{prop-mono}, for all $0\leq t\leq T$, we deduce   
\begin{eqnarray*}
    \frac{d}{dt}\left( \int_{\mathcal{C}_{\theta}}\log u^{T}(\xi, t)\ell(\xi) d\sigma\right)=- \int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{K(\xi, t)}{u^{T}(\xi,t)}}-\sqrt{\frac{u^{T}(\xi,t)}{K(\xi,t)}}\right)^{2}\ell(\xi) d\sigma,
\end{eqnarray*} by integrating over $t\in [0, T]$ and taking \eqref{eq-rewrite-u-T-at-time-T} into account yield
\begin{eqnarray}
  &&  \int_{\mathcal{C}_{\theta}}(\log u^{T}(\xi,0))\ell (\xi)d\sigma-\omega_\theta \mathcal{E}_{\theta}(\widehat{\Sigma}_T)=\int_{0}^{T}\int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{K(\xi, t)}{u^{T}(\xi,t)}}-\sqrt{\frac{u^{T}(\xi,t)}{K(\xi,t)}}\right)^{2}\ell(\xi) d\sigma dt \notag\\
    &\geq & \int_{0}^{T_{1}}\int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{K(\xi, t)}{u^{T}(\xi,t)}}-\sqrt{\frac{u^{T}(\xi,t)}{K(\xi,t)}}\right)^{2}\ell(\xi) d\sigma dt.    \label{ineq-estimate-on-entropy-refined}\end{eqnarray}
 Due to \eqref{aT}, when $T\to +\infty$, there holds 
 $$u^{T}(\xi, t)\to u(\xi, t) ~\text{ uniformly  for all } ~(t, \xi)\in [0,T_{1}]\times \mathcal{C}_{\theta}, $$ 
together with by letting $T\rightarrow +\infty$ in \eqref{ineq-estimate-on-entropy-refined}, we obtain
\begin{eqnarray*}
    \int_{\mathcal{C}_{\theta}}(\log u(\xi, 0))\ell(\xi) d\sigma- \omega_\theta \mathcal{E}_{\infty}\geq  \int_{0}^{T_{1}}\int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{K(\xi, t)}{u(\xi,t)}}-\sqrt{\frac{u(\xi,t)}{K(\xi,t)}}\right)^{2}\ell(\xi) d\sigma dt.
\end{eqnarray*}
Thus \eqref{limit prop} holds for $t=0$. Changing $t=0$ to another time $t>0$ and letting $T_{1}\rightarrow +\infty$, we can show that \eqref{limit prop} holds for all $t>0$.

\label{thm-C0}
 Suppose that $u(\xi,t)$ is a positive solution to flow \eqref{eq-scalar-capillary-support-normalized-GCF} with $\theta \in (0,\pi/2)$  and  ${\rm{Vol}}(\widehat\Sigma_0 )={\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$. Then there exists  positive constants $C=C(n, \Sigma_{0})$ and $T_{0}=T_{0}(\Sigma_{0})$, such that 
    \begin{eqnarray}\label{est-u-two-side-bound}
        \frac{1}{C}\leq u(\xi, t)\leq C, ~~~\text{ for all }\xi \in \mathcal{C}_\theta,~ t\geq T_{0}. \label{C0}
    \end{eqnarray}

The uniform upper bound of $u(\xi, t)$ follows from Proposition \ref{radius}, Proposition \ref{prop-mono}, and \eqref{double-control}. Hence, it remains to establish a positive uniform lower bound for the solution.
 By Proposition \ref{pro-limit}, we obtain
 \begin{eqnarray*}
     \mathcal{E}_{\infty}\leq \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u(\xi,t)\right)\ell(\xi) d\sigma\leq \mathcal{E}_{\theta}(\widehat\Sigma_t ), \quad \forall~ t\geq 0,
 \end{eqnarray*}
 that is,
 \begin{eqnarray}\label{t-limit}
     0\leq \mathcal{E}_{\theta}(\widehat\Sigma_t)-\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u(\xi, t)\right)\ell(\xi) d\sigma \rightarrow 0, \quad {\rm{as}}~t\rightarrow +\infty, \end{eqnarray}
together with \eqref{ineq-stability-estimate} and \eqref{entropy upper}, it follows that the capillary entropy point $z_e(\widehat\Sigma_t)$ of $\widehat\Sigma_t$ satisfies
\begin{eqnarray*}
    |z_e(\widehat\Sigma_t)-0|\to 0, ~~~\text{ as } t\to +\infty.
\end{eqnarray*} In view of Theorem \ref{thm-lim-Hausdorff-distance} (2), it follows that  there exists a sufficiently large constant $T_{0}=T_{0}(\Sigma_{0})>0$ such that  
\begin{eqnarray*}
    \text{dist}(0, \Sigma_t) \geq \varepsilon_0, ~~~~\text{for all } t\geq T_0,
\end{eqnarray*}where $\varepsilon_0$ is a positive constant, depending only on $n$ and $\Sigma_0$. Thus, in turn, implies that there exists a constant $C=C(n,\Sigma_0)>0$ such that $$u(\xi, t) \geq \frac{1}{C}, ~~~\text{ for all }\xi \in \mathcal{C}_\theta,~ t \geq T_0.$$ This completes the proof.

Along flow \eqref{Support-Normalized},  we have the evolution equations.
    \begin{enumerate}
        \item  The capillary support function $u$ satisfies
        \begin{eqnarray}\label{eq-Lu}
            \mathcal{L} u=2  K a^{ij}\nabla_{i}u \nabla_{j}\ell-(n+1) K+  KH u+u,
        \end{eqnarray}
   and                                
        \begin{eqnarray}\label{eq-Neumann-u}
            \nabla_{\mu}u=0, ~~\text{ on } \partial\mathcal{C}_{\theta}.
        \end{eqnarray}
        \item The Gauss curvature $K$ satisfies
        \begin{eqnarray}\label{eq-LK}
            \mathcal{L}K=2 Ka^{ij}\nabla_{i}K\nabla_{j}\ell+ K^{2}H-n K,
        \end{eqnarray}
and                              
    \begin{eqnarray}\label{eq-Neumann-K}
        \nabla_{\mu}K=0,  ~~\text{ on } \partial\mathcal{C}_{\theta}.
    \end{eqnarray}        
    \end{enumerate}

\label{prop-F-lower}
Let $\Sigma_t$ be the solution of flow \eqref{GCF-capillary-normalized} with $\theta \in (0,\pi/2)$.  If ${\rm{Vol}}(\widehat\Sigma_0 )={\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$, then there exists a positive constant $C$, depending only on $n$ and $\Sigma_{0}$, such that
    \begin{eqnarray}\label{K-upper}
        K(\xi,t)\leq C, ~~\text{ for all } (\xi,t)\in \mathcal{C}_\theta\times[0, +\infty).
    \end{eqnarray}

Let $T\in [0, T^{\ast})$ and $\widetilde{X}(\xi, \tau)$ be the solution to flow \eqref{GCF-capillary-2} in $[0, T]$. For all $\tau \in [0, T]$, let $\rho_{-}(\widehat{\widetilde \Sigma}_{\tau}, \theta)$ and $\rho_{+}(\widehat{\widetilde\Sigma}_{\tau}, \theta)$ be the capillary inner and outer radius of $\widehat{\widetilde{\Sigma}}_{\tau}$ respectively.  For brevity, we abbreviate $\rho_{-}(\widehat{\widetilde\Sigma}_{\tau}, \theta)$ as $\rho_{1}(\tau)$ and $\rho_+(\widehat{\widetilde\Sigma}_{\tau}, \theta)$ as $\rho_{2}(\tau)$.  From Theorem \ref{main-existence}, there exists a point $\widetilde z_{0}\in \overline{\mathbb{R}^{n+1}_{+}}$ such that
\begin{eqnarray*}
   \widehat{\mathcal{C}_{\rho_{1}(T), \theta}(\widetilde z_{0})}\subset \widehat{\widetilde\Sigma}_{\tau}, \quad {\rm{for~all}}~\tau \in [0, T].
\end{eqnarray*}
Picking $c_{0}=\frac{1}{2}\rho_{1}(T)$ in \eqref{K-upper-bound}, we obtain 
\begin{eqnarray*}
    \widetilde{K}(\xi, T)\leq \max\left\{ 2^{n+1}\left(\frac{n+1}{n}\right)^{n}\frac{ \widetilde u_{\widetilde z_{0}}(\xi,T)
    }{ \rho_{1}(T)^{1+n}}, \frac{ \widetilde{u}_{\widetilde z_{0}}(\xi, T)\widetilde{K}(\xi, 0)}{\rho_{1}(T)}
   \right \}.
\end{eqnarray*}
where $\widetilde{u}_{\widetilde z_{0}}(\xi, T)$ is the capillary support function of $\widehat{\widetilde{\Sigma}}_{T}$ with respect to the point $\widetilde z_{0}$.  Denote $t\coloneqq \frac{1}{n+1}\log \left(\frac{{\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})}{{\rm{Vol}}(\widehat{\widetilde\Sigma}_{T})}\right)$.   
In view of the rescaling, we obtain 
\begin{eqnarray}\label{upper-K}
    K(\xi, t)&\leq& \max\left\{ 2^{n+1}\left(\frac{n+1}{n}\right)^{n} \frac{2\rho_{+}(\widehat{\Sigma}_{t}, \theta)}{\rho_{-}(\widehat{\Sigma}_{t}, \theta)^{1+n}}, \frac{2\rho_{+}(\widehat{\Sigma}_{t}, \theta)}{\rho_{-}(\widehat{\Sigma}_{t}, \theta)} K(\cdot, 0)
    \right\}.



\end{eqnarray}
Combining Proposition \ref{radius}, Proposition \ref{prop-mono} and Proposition \ref{volume-preserving}, we have 
\begin{eqnarray}\label{upper-ratio}
    \frac{\rho_{+}(\widehat{\Sigma}_{t}, \theta)}{\rho_{-}(\widehat{\Sigma}_{t}, \theta)}\leq \frac{C^{2}e^{(n+1)\mathcal{E}_{\theta}(\widehat{\Sigma}_{t})}}{ {\rm{Vol}}(\widehat{\Sigma}_{t})}\leq \frac{C^{2}e^{(n+1)\mathcal{E}_{\theta}(\widehat{\Sigma}_{0})}}{{\rm{Vol}(\widehat{\mathcal{C}_{\theta}})}},
\end{eqnarray}
and 
\begin{eqnarray*}
    \frac{\rho_{+}(\widehat{\Sigma}_{t}, \theta)}{\rho_{-}(\widehat{\Sigma}_{t}, \theta)^{n+1}}\leq \frac{C^{n+2} e^{\left(1+n(n+1)\right)\mathcal{E}_{\theta}(\widehat\Sigma_{0})}}{{\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})^{n+1}},
\end{eqnarray*}
together with \eqref{upper-K} and  \eqref{upper-ratio}, we complete the proof of \eqref{K-upper}.

\label{pro-F-upper}
Let $\Sigma_t$ be the solution of flow \eqref{GCF-capillary-normalized}  with $\theta \in (0,\pi/2)$.  If ${\rm{Vol}}(\widehat\Sigma_0 )={\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$, then there exists a positive constant $C$ depending on $n$ and $\Sigma_{0}$, such that
    \begin{eqnarray}\label{K-lower}
        K(\xi,t)\geq C,~~\text{ for all } (\xi,t)\in \mathcal{C}_\theta\times[T_0, +\infty). 
    \end{eqnarray}

Define
   \begin{eqnarray*}
       P(\xi,t) \coloneqq \log (Ku^{\gamma}), ~~~\text{ for }\xi\in \mathcal{C}_\theta,~~ t\geq  T_0,
   \end{eqnarray*}
   where $\gamma>0$ is a constant to be determined later.
From \eqref{eq-Neumann-u} and \eqref{eq-Neumann-K}, we have
   \begin{eqnarray}\label{P-neumann}
        \nabla_{\mu}P=0, \quad  {\rm{on}}~ \partial\mathcal{C}_{\theta}. 
   \end{eqnarray} 
   Then we know $P$ attains its minimum value at some interior point, say $\xi_0\in \mathcal{C}_\theta\setminus\partial \mathcal{C}_\theta$. Next, all the calculations are done at the minimum value point $\xi_0$. First,  we have
   \begin{eqnarray}\label{one-deri}
   0=\nabla_i P=    \frac{\nabla_i K}{K}+\frac{\gamma \nabla_{i}u}{u},
   \end{eqnarray}
   and by using Eq. \eqref{eq-Lu}, \eqref{eq-LK}, and  \eqref{one-deri}, it follows that 
   \begin{eqnarray}\label{two-deri}
      0&\geq & \mathcal{L}P\notag  = \frac{1}{K}\mathcal{L}K+\frac{\gamma}{u}\mathcal{L}u+ \ell Ka^{ij} \left(\frac{\nabla_{i}K\nabla_{j}K}{K^{2}}+\gamma\frac{\nabla_{i}u \nabla_{j}u}{u^{2}} \right)\notag  \\
       &\geq &\frac{1}{K}\mathcal{L}K+\frac{\gamma}{u}\mathcal{L}u\geq (\gamma-n)-\frac{(n+1)\gamma }{u}K.     
   \end{eqnarray}
By choosing $\gamma = 2 + n$ and substituting \eqref{C0} into \eqref{two-deri}, we conclude that
\begin{eqnarray*}
P(\xi, t) \geq P(\xi_0, t) \geq \log\left(\frac{u^{n+3}}{(n+1)(n+2)}\right).
\end{eqnarray*}
Applying \eqref{est-u-two-side-bound} once more, we obtain \eqref{K-lower}.

\label{cur-est}
Let $h(\xi, t)$ be the solution of flow \eqref{Support-Normalized} with $\theta \in (0,\pi/2)$. 
 Suppose that ${\rm{Vol}}(\widehat\Sigma_0 )={\rm{Vol}}(\widehat{\mathcal{C}_{\theta}})$, then there exist A  positive constant $C$,  depending only on $n$ and $\Sigma_{0}$, such that
    \begin{eqnarray}\label{principal-radius-bi-estimates}
        \frac{1}{C} I\leq (h_{ij}+h\sigma_{ij})\leq C I, ~~\text{ for all } (\xi,t)\in \mathcal{C}_\theta\times[T_0, +\infty),
    \end{eqnarray}
  where $T_{0}$ is a positive constant given in Theorem \ref{thm-C0}.

Since $\nabla^{2}h+h\sigma$ is positive definite, and the upper and lower bound of $K$ implies that it suffices to prove the upper bound of the eigenvalues of $\nabla^{2}h+h\sigma$.   Similar to the proof of Proposition \ref{curvature est}, we consider the function 
    \begin{eqnarray*}
        \Phi\coloneqq \Delta h+n h.
    \end{eqnarray*}
Recall from \eqref{boundary of Phi}, there holds  $$\nabla_{\mu}\Phi
    \leq 0 \text{ on } \partial\mathcal{C}_{\theta}.$$ Thus, we know that $\Phi$ attains its maximum value within $\mathcal{C}_\theta$ at some interior point, say $\xi_{0}\in \mathcal{C}_{\theta}\setminus \partial \mathcal{C}_{\theta}$. By performing calculations similar to those in Proposition \ref{curvature est}, at $\xi_0$, we have
    \begin{eqnarray}
      0\leq  \mathcal{L}\Phi&=&\Phi-\ell K\Phi H- \left[(n\ell-1) nK 
     - \ell K a^{kp} \nabla_{i}a_{pq} a^{ql}\nabla_{i}a_{kl} \right.\notag  \\
     &&\left.- \ell K a^{pq}\nabla_{i}a_{pq}a^{kl}\nabla_{i}a_{kl} -2  \nabla\ell \cdot \nabla K\right].~~~~~~~~~~\label{Phi evo}
    \end{eqnarray}
Together with \eqref{Kalpha upper} and  \eqref{K-upper}, we get
  \begin{eqnarray}
 &&  K \left[ -  \ell \sum_{k,l,i} a^{kk}a^{ll}(\nabla_{i}a_{kl})^2- \alpha \ell  \sum_i \left(\sum_k a^{kk}\nabla_{i}a_{kk} \right)^2-2\cos\theta \<e_i,e\> a^{kk} \nabla_{i}a_{kk} \right] \notag  \\&& \leq  C K \leq C.~~~\label{Kalpha-2}
\end{eqnarray}
By the Newton-Maclaurin inequality, we obtain
\begin{eqnarray}\label{H-low bound}
   H= \frac{\sigma_{n-1}(A)}{\sigma_{n}(A)}\geq n\left(\frac{\sigma_{1}(A)}{n\sigma_{n}(A)}\right)^{\frac{1}{n-1}}=n^{\frac{n-2}{n-1}}K^{\frac{1}{n-1}}\Phi^{\frac{1}{n-1}}. 
\end{eqnarray}
Inserting \eqref{Kalpha-2} and \eqref{H-low bound} into  \eqref{Phi evo}, we have 
\begin{eqnarray*}
 0\leq \Phi -n^{\frac{n-2}{n-1}}\ell (K\Phi)^{\frac{n}{n-1}}-(n\ell-1)nK-C,   
\end{eqnarray*}
Using \eqref{K-upper}, \eqref{K-lower} again, we conclude that $$\Phi\leq C,$$ which yields the upper bound in \eqref{principal-radius-bi-estimates} and the lower bound follows together with \eqref{K-lower}. This completes the proof.

In view of Theorem \ref{thm-C0}, Proposition \ref{prop-F-lower}, Proposition \ref{pro-F-upper} and Proposition \ref{cur-est}, we conclude that the solution $u$ of flow \eqref{eq-scalar-capillary-support-normalized-GCF} satisfies 
\begin{eqnarray*}
    \|u(\cdot, t)\|_{C^{2}(\mathcal{C}_{\theta})}\leq C,
\end{eqnarray*}
 where the positive constant $C$ only  depends on $n$ and $\Sigma_{0}$. Thus by the standard parabolic fully nonlinear equation theory with Neumann boundary value condition (see, e.g., \cite[Theorem 6.1, Theorem 6.4 and Theorem 6.5]{Dong}, and also \cite[Theorem 14.23]{Lieberman-book-parabolic}),  for any integer $k\geq 2$ and $\alpha\in (0,1) $, there holds
\begin{eqnarray}\label{est}
    \|u(\cdot, t)\|_{C^{k, \alpha}(\mathcal{C}_{\theta})}\leq C.
\end{eqnarray}
Given any $T>0$, and a number sequence $\{t_{j}\}_{j\geq 1}$ with $t_j\nearrow + \infty$, consider the sequence functions 
\begin{eqnarray}\label{uj}
u_{j}(\xi, t)\coloneqq u(\xi, t+t_{j})=\frac{h(\xi, t+t_j)}{\ell(\xi)}.  
\end{eqnarray}
For each $j\geq 1$, we see that $\{u_{j}\}_{j\geq 1}$ are still the solutions of flow  \eqref{eq-scalar-capillary-support-normalized-GCF} and satisfy  \eqref{est}. This implies $u_{j}(\xi,t)$ (up to a subsequence) converges in $C^{\infty}$ topology to a limit function $u_{\infty}(\xi,t)$ for all $(\xi,t)\in \mathcal{C}_\theta \times [-T,T]$, and $u_{\infty}$  satisfies the flow  \eqref{eq-scalar-capillary-support-normalized-GCF}.  Moreover, Theorem \ref{thm-C0} implies that $u_{\infty}>0$.                                                                                                          
On the other hand, together with \eqref{t-limit}, it implies that $u_{\infty}$  satisfies 
    \begin{eqnarray*}
     \int_{\mathcal{C}_{\theta}}\left(\log u_{\infty}(\xi,t)\right)\ell(\xi)d\sigma=\lim\limits_{j\rightarrow +\infty} \int_{\mathcal{C}_{{\theta}}}\left(\log u_{j}(\xi, t)\right)\ell (\xi)d\sigma=\omega_\theta \mathcal{E}_{\infty},
    \end{eqnarray*}
    together with the proof of Proposition \ref{prop-mono}, it yields
    \begin{eqnarray*}
   0=\frac{d}{dt}\left( \int_{\mathcal{C}_{\theta}}(\log u_{\infty}(\xi, t))\ell(\xi) d\sigma\right)=- \int_{\mathcal{C}_{\theta}}\left(\sqrt{\frac{u_{\infty}(\xi,t)}{K(\xi, t)}}-\sqrt{\frac{K(\xi, t)}{u_{\infty}(\xi, t)}}\right)^{2}\ell(\xi) d\sigma,
   \end{eqnarray*}
which in turn implies that 
    \begin{eqnarray*}
        \frac{u_{\infty}(\xi, t)}{K(\xi,t)}=\frac{K(\xi, t)}{u_{\infty}(\xi, t)},
    \end{eqnarray*}
combining with the fact that $u_{\infty}(\xi, t)$ satisfies the flow \eqref{eq-scalar-capillary-support-normalized-GCF}, we obtain $$\partial_t u_{\infty} (\xi, t)=0.$$ Hence $u_{\infty}(\cdot)\coloneqq u_{\infty}(\cdot, t)$ satisfies 
    \begin{eqnarray*}
    \left\{
\begin{array}{llll}
 u_{\infty} &=&\frac 1 {\det \left(\nabla^2 (\ell u_\infty)+\ell u _\infty\sigma \right)}   & \text{ in } ~\mathcal{C}_\theta,\\ 
	\nabla_\mu u_{\infty} &=& 0 & \text{ on }~ \partial \mathcal{C}_\theta, \end{array}  \right.
\end{eqnarray*} which is equivalent to \eqref{eq-soliton-normalized-GCF}, by  taking into account \cite[Proposition 2.6]{MWWX}.  
Therefore, we obtain that after passing to a subsequence, the solution $\{u_j\}_{j\geq 1}$ of \eqref{eq-scalar-capillary-support-normalized-GCF} smoothly converges to a smooth function $u_\infty$, which satisfies Eq. \eqref{eq-soliton-normalized-GCF}. 

Finally, we prove that $u(\xi,t)$ globally converges in the $C^{\infty}$-topology to $u_{\infty}(\xi, t)$ as $t\rightarrow +\infty$. We proceed by contradiction. If not, then there there exist $l\in \mathbb{N}$ and a sequence $\{t_{j}\}_{j\geq 1}$ with $t_j\nearrow + \infty$, such that 
\begin{eqnarray}\label{m-deriv}
    \sup\limits_{\mathcal{C}_{\theta}}|(\nabla^{l}u)(\xi, t_{j})-(\nabla^{l}u_{\infty})(\xi)|\geq \tau,
\end{eqnarray}
 for some positive constant $\tau$. On the other hand, we consider the sequence $u_{j}(\xi,t)\coloneqq u(\xi,t+t_j)$ defined in way of \eqref{uj}, we see that $u_{j}(\xi, t)$ (up to a subsequence) converges in $C^{\infty}$ topology to $u_{\infty}(\xi)$ on $\mathcal{C}_{\theta}\times \{0\}$. This implies  $u_{t_{j}}(\xi, 0)$ converges in $C^{\infty}$ topology to $u_{\infty}(\xi)$ on $\mathcal{C}_{\theta}$, which is  a contradiction to \eqref{m-deriv}. Hence, we complete the proof.

Let $\widehat\Sigma\in \mathcal{K}_\theta$ be a capillary convex body,  the capillary $\alpha$-entropy functional $\mathcal{E}_{\alpha,\theta}$ for $\widehat\Sigma$ is defined by
\begin{eqnarray}\label{cap-entropy-alpha}
    \mathcal{E}_{\alpha,\theta}(\widehat\Sigma)\coloneqq \sup_{z_0\in {\rm{int}}(\widehat{\partial\Sigma})}    \mathcal{E}_{\alpha,\theta}(\widehat\Sigma,z_0),
\end{eqnarray} and 
\begin{eqnarray*} 
    \mathcal{E}_{\alpha,\theta}(\widehat\Sigma,z_0)\coloneqq \begin{cases}
        \frac{\alpha}{\alpha-1} \log\left( \frac 1 {\omega_\theta} \int_{\mathcal{C}_\theta} u_{z_0}(\xi)^{1-\frac 1 \alpha} \ell(\xi) d\sigma \right),~~ &\alpha\neq 1,\\
        \frac 1 {\omega_\theta}\int_{\mathcal{C}_\theta} (\log u_{z_0}(\xi)) \ell(\xi)  d\sigma, ~~ &\alpha=1,
    \end{cases}
\end{eqnarray*}where $d\sigma$ is the standard area element on $\mathcal{C}_\theta$ and $\omega_\theta$ is the capillary area of $\mathcal{C}_\theta$.

{\it   Given $\alpha > \frac{1}{n+2}$ and $\theta \in (0, \pi)$, suppose that $h$ is a positive, strictly convex function in $\mathcal{C}_\theta$ and solves
\begin{eqnarray}
\left\{
\begin{array}{llll}
	h\det^\alpha(\nabla^2 h+h\sigma) = \ell & \text{  in } ~~ \mathcal{C}_\theta , \\ 
	\nabla_\mu h= \cot\theta h & \text{ on }~~ \partial \mathcal{C}_\theta,\end{array} \right.
\end{eqnarray}
then $h=\ell$.}

Let $K$ be a convex body (i.e., a compact, convex set with non-empty interior) contained in $\overline{\mathbb{R}^{n+1}_+}$. The normal cone of $K$ at the point $x\in \partial K$, denoted $\mathcal N_x K$, is defined by
\begin{eqnarray*}
\mathcal N_x K\coloneqq \left\{ \zeta \in \mathbb{S}^n \mid \<\zeta,y - x\> \leq 0,~~\text{ for all } y \in K \right\}.
\end{eqnarray*}

\label{defn-general-capillary-convex-body}
  Let $K$ be a convex body contained in $\overline{\mathbb{R}^{n+1}_+}$. The boundary of $K$ consists of two components: one is $K_{u}\coloneqq \partial  K\cap \mathbb{R}^{n+1}_{+}$, and the other, denoted by $K_{f}\coloneqq \partial K\cap \partial\overline{\mathbb{R}^{n+1}_{+}}$, lies on $\partial \overline{\mathbb{R}^{n+1}_+}$. These two components share a common boundary, denoted by $\partial K_f$. We require that $K_u$ is nonempty and that $K_f$ contains interior points (relative to $\partial \mathbb{R}^{n+1}_+$).
We refer to such a $K$ as a convex body restricted to $\overline{\mathbb{R}^{n+1}_+}$.

\label{defn-angle}
  Let $K\in \mathcal G$ and $x\in \partial K_f$, we define the contact angle $\vartheta=\vartheta (x)\in (0,\pi)$ of $K$ at the point $x \in \partial K_{f}$  by 
  \begin{eqnarray*}
      \cos \vartheta= \sup\limits_{\zeta\in \mathcal N_{x}K}\<\zeta, E_{n+1}\>.
  \end{eqnarray*}
For all $x\in \partial K_f$, if $\vartheta(x)\leq \theta$ for some fixed constant $\theta\in(0, \pi)$, then we call such $K$ the $\theta$-capillary convex body in $\overline{\mathbb{R}^{n+1}_+}$.

We start by showing that $\mathcal{F}_{\theta}(K)$ is well-defined. It suffices to show that
\begin{eqnarray}\label{ineq-two-sides-est-F-theta}
    -C\leq \mathcal{F}_{\theta}(K)\leq C,
\end{eqnarray} 
where $C$ is a positive constant depending only on $n, \rho_{+}(\widehat{K})$ and ${\rm{Vol}}(K)$.  In fact, the upper bound in \eqref{ineq-two-sides-est-F-theta} follows directly  from 
\begin{eqnarray*}
    \mathcal{F}_{\theta}(K)\leq \frac{1}{\omega_{\theta}}\int_{\mathbb{S}^{n}_{\theta}} \log \left(2\rho_{+}(K) \right)\ell(\zeta)
d\sigma =\log \left(2\rho_{+}({K}) \right).
\end{eqnarray*}
Next, we proceed to show the lower bound in \eqref{ineq-two-sides-est-F-theta}. Let $\widetilde K$ be the bounded domain by reflecting $K$ with respect to the hyperplane $\partial\mathbb{R}^{n+1}_+$. We \textbf{claim} that $\widetilde K$ is a bounded closed convex body in $\mathbb{R}^{n+1}$. Since  $\bigcup\limits_{x\in K_{u}}\mathcal{N}_{x}K$ is  a connected component of $\mathbb{S}^{n}$ and $E_{n+1}\in \bigcup\limits_{x\in K_{u}}\mathcal N_{x}K$, and from $K\in\mathcal{G}_{\theta}$, we have $\vartheta(x) \leq \theta$ for all $x\in \partial K_{f}$ with $\theta\in (0, \pi/2)$, then we conclude that
$$\overline{\bigcup\limits_{x\in K_{u}}\mathcal N_{x} K}\subset \mathbb{S}^{n}_{\theta},$$ 
which implies the claim. We denote by $\widetilde z_{s}$ the classical Santal\'o point of  $\widetilde {K}$, using the symmetry of $\widetilde K$ with respect to $\partial\mathbb{R}^{n+1}_+$ and \eqref{sym}, it implies   
\begin{eqnarray}\label{eq-santalo-wilde-K-interior}
\widetilde z_{s}\in {\rm{int}}(K_{f}).
\end{eqnarray}
From \cite[Page 547]{Sch} or \cite[(1.1)]{San}, there holds
\begin{eqnarray}\label{eq-volume-polar-body}
    {\rm{Vol}}(\widetilde K_{ \widetilde z_{s}}^{\ast})=\frac{1}{n+1}\int_{\mathbb{S}^{n}}\frac{1}{h_{ \widetilde z_{s}}^{n+1}(\zeta)}d\sigma,
\end{eqnarray}
where $\widetilde K_{ \widetilde z_{s}} ^{\ast}$ and $h_{\widetilde z_{s}}$ denote the polar body and support function of $\widetilde K$ with respect to the point $\widetilde z_{s}$, respectively. In view of \eqref{class-BS}, $\text{Vol}(\widetilde K)=2\text{Vol}(K)$ and \eqref{eq-volume-polar-body}, we obtain 
\begin{eqnarray}\label{zs upper}
    \int_{\mathbb{S}^{n}}\frac{1}{h_{ \widetilde z_{s}}^{n+1}(\zeta)}d\sigma\leq \frac{ (n+1){\rm{Vol}}(\mathbb{B}^{n+1})^{2}}{2{ {\rm{Vol}}(K)}}.
\end{eqnarray}
Since $\ell(\zeta)=1-\cos\theta\<\zeta, E_{n+1}\><1$ on $\mathbb{S}^{n}_{\theta}$, then by applying the Jensen's inequality as \eqref{Jen-ine}, it yields
\begin{eqnarray}\label{upper-zs}
    \exp\left(\frac{1}{\omega_{\theta}}\int_{\mathbb{S}_{\theta}^{n}}  \log \left(\frac{1}{u_{ \widetilde z_{s}}^{n+1}(\zeta)}\right) \ell(\zeta)d\sigma  \right) &\leq& \frac{1}{\omega_{\theta}}\int_{\mathbb{S}_{\theta}^{n}}\frac{1}{u_{ \widetilde z_{s}}^{n+1}(\zeta)}\ell(\zeta)d\sigma \notag \\
    &\leq& \frac{1}{\omega_{\theta}}\int_{\mathbb{S}_{\theta}^{n}}\frac{1}{h_{\widetilde z_{s}}^{n+1}(\zeta)}d\sigma.
\end{eqnarray}
Inserting \eqref{zs upper} into \eqref{upper-zs}, we obtain 
$$\frac{1}{\omega_{\theta}} \int_{\mathbb{S}^{n}_{\theta}}\left(\log u_{\widetilde z_{s}}(\zeta)\right)\ell(\zeta) d\sigma\geq -C,$$
 together with \eqref{eq-entropy-on-K} and \eqref{eq-santalo-wilde-K-interior},  it follows  that $$\mathcal{F}_{\theta}(K)\geq -C,$$ thus we complete the proof of \eqref{ineq-two-sides-est-F-theta}.
 Notice that $K_{f}$ is a bounded closed convex body in $\mathbb{R}^{n}=\partial{\overline{\mathbb{R}^{n+1}_{+}}}$, following the same argument as in the proof of Propositions \ref{prop-exist-cap-entropy-point} and \ref{lem entropy}, we can show there exists a unique interior point $z_{e}\in \text{int}( K_f)$, such that $\mathcal{F}_{\theta}(K)=\frac{1}{\omega_{\theta}}\int_{\mathbb{S}^{n}_{\theta}}\left(\log u_{z_{e}}(\zeta)\right)\ell(\zeta)d\sigma$. This completes the proof.

We just need to show that \begin{eqnarray}\label{angle-decrease}
       \vartheta(x)\leq \theta, \quad \text{for all }x\in \partial (\widehat\Sigma_{\star}\cap \partial{ \mathbb{R}^{n+1}_{+}}).
   \end{eqnarray}
By assumption and \cite[Lemma 1.8.14]{Sch}, we have
\begin{eqnarray}\label{sup-func}
    h_{\widehat\Sigma _{k}}(\zeta)\coloneqq \sup\limits_{y\in \widehat{\Sigma}_{k}}\<y, \zeta\>\rightarrow h_{\widehat{\Sigma}_{\star}}(\zeta),  ~\forall~ \zeta\in \mathbb{S}^{n}, \text{ as } k\to +\infty,
\end{eqnarray}
where $h_{\widehat{\Sigma}_{k}}$ and $h_{\widehat{\Sigma}_{\star}}$ are the classical support functions of $\widehat{\Sigma}_{k}$ and 
$\widehat{\Sigma}_{\star}$ with respect to the origin respectively.

Given $\zeta\in \mathbb{S}^{n}\setminus {\rm{int}}(\mathbb{S}^{n}_{\theta})$, then for each $\widehat\Sigma_{k}\in\mathcal{K}_{\theta}$, there exists a point $x_{k}\in \partial\Sigma_{k}$, such that $h_{\widehat{\Sigma}_{k}}(\zeta)=\<x_{k}, \zeta\>$. Let $k\rightarrow +\infty$, we have $x_{k}\rightarrow x$ (possibly up to a subsequence) for some $x\in \partial (\widehat{\Sigma}_{\star}\cap \partial\overline{\mathbb{R}^{n+1}_{+}})$. Together with\eqref{sup-func} implies 
$  \zeta \in \mathcal{N}_{x}\widehat{\Sigma}_{\star}$. Hence we obtain 
\begin{eqnarray*}
    \mathbb{S}^{n}\setminus {\rm{int}}(\mathbb{S}^{n}_\theta)\subset \bigcup_{x\in\partial (\widehat\Sigma_{\star}\cap \partial { \mathbb{R}^{n+1}_{+}}) }\mathcal{N}_{x}\widehat{\Sigma}_{\star}.
\end{eqnarray*}
By  Definition \ref{defn-angle}, we conclude that \eqref{angle-decrease} holds.

\label{thm-lim-Hausdorff-distance}
    Let $\theta\in (0, \pi/ 2)$. We have
    \begin{enumerate}
        \item Suppose that $\{\widehat\Sigma_{k}\}_{k\geq 1}\subset  \Gamma_{A}$, and 
    $\lim\limits_{k\rightarrow +\infty}\widehat\Sigma_{k}=\widehat\Sigma_\star$  in Hausdorff distance sense. Then $\widehat{\Sigma}_{\star}\in \mathcal{G}_{\theta}$ and 
    \begin{eqnarray}\label{lim}
        \lim\limits_{k\rightarrow +\infty}\mathcal{E}_{\theta}(\widehat{\Sigma}_{k})=\mathcal F_{\theta}(\widehat{\Sigma}_{\star}).
    \end{eqnarray} 
    \item  Then there exists a constant $\delta > 0$, depending only on $n$ and $A$, such that for all $\widehat{\Sigma}\subset \Gamma_{A}$, the capillary entropy point $z_e(\widehat{\Sigma})$ of $\widehat{\Sigma}$ satisfies 
    \begin{eqnarray}\label{dist}
{\rm{dist}}\left(z_e(\widehat{\Sigma}), \Sigma\right) \geq \delta.
\end{eqnarray}

    \end{enumerate}

\textit{(1)}
Since the volume is preserved along the Hausdorff convergence, this implies that $\widehat{\Sigma}_{\star}$ cannot collapse into a lower-dimensional convex set, so we obtain $\widehat{\Sigma}\in \mathcal{G}$. From Proposition \ref{prop-angle-decrease} above, we have $\widehat{\Sigma}_{\star}\in \mathcal{G}_{\theta}$. Next, we proceed to prove \eqref{lim}.




From Proposition \ref{radius} and \eqref{double-control}, given $\widehat \Sigma\in \Gamma_{A}$, there exists a positive constant $C_0$, depending only on $n$ and $A$, such that
\begin{eqnarray}\label{u-upper}
    u_z^{\Sigma}\leq 2\rho_+(\widehat\Sigma,\theta) \leq 2 C e^{\mathcal{E}_\theta(\widehat\Sigma)} \leq 2Ce^A\eqqcolon C_0,
\end{eqnarray}
where $u_z^{\Sigma}$ is the capillary support function of $\widehat\Sigma$ with respect to the point $z\in  \widehat{\partial \Sigma}$.

 By
 Proposition \ref{prop-small angle}, we derive that the capillary entropy point $ z_e(\widehat{\Sigma}_\star)$ of $\widehat\Sigma_\star$ lies in ${\rm{int}}(\widehat{\partial\Sigma}_\star)$ with $\widehat{\partial \Sigma}_{\star}\coloneqq \widehat{\Sigma}_{\star}\cap \partial \overline{\mathbb{R}^{n+1}_{+}}$, therefore, for $k$ sufficiently large, we have $ z_e({\widehat\Sigma_\star})\in {\rm{int}}(\widehat{\partial\Sigma}_k)$. In view of \eqref{u-upper} and the dominated convergence theorem, we derive
\begin{eqnarray}\label{inf}
  \mathcal F_{\theta}(\widehat\Sigma_\star)&=&\frac{1}{\omega_{\theta}}\int_{\mathbb{S}^{n}_{\theta}}\left(\log u_{z_e(\widehat\Sigma_\star)}^{\Sigma_\star}(\zeta)\right)\ell (\zeta)d\sigma\notag \\
    &=&\lim\limits_{k\rightarrow\infty}\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u_{  z_e(\widehat\Sigma_\star)}^{\Sigma_{k}}(\xi)\right)\ell(\xi) d\sigma\leq \lim\limits_{k\rightarrow +\infty}\mathcal{E}_{\theta}(
    \widehat\Sigma_k ),~~~
\end{eqnarray}where $u_{ z_e(\widehat\Sigma_\star)}^{\Sigma_k}$ denote the capillary support function of $\widehat{\Sigma}_k$ with respect to the point $ z_e(\widehat{\Sigma}_\star)$ and $u_{  z_e(\widehat\Sigma_\star)}^{\Sigma_\star}=\frac{h^{ \Sigma_{\star}}_{{z}_{e}(\widehat\Sigma_{\star})}}{\ell}$, where $h^{ \Sigma_{\star}}_{{z}_{e}(\widehat\Sigma_{\star})}$ is the classical support function of $\widehat{\Sigma}_{\star}$ with respect to the point ${z}_{e}(\widehat{\Sigma}_{\star})$.
On the other hand,  Proposition \ref{lem-low-entroy} implies 
\begin{eqnarray*}
 \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\log \left(\frac{u_{z_e(\widehat\Sigma_{k})}^{\Sigma_{k}}(\xi)}{C_0}\right)\ell(\xi) d\sigma=\mathcal{E}_{\theta}(\widehat\Sigma_k )-\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}} (\log C_0) \ell(\xi) d\sigma\geq -C,
\end{eqnarray*}for some positive constant $C$, depending only on $n$ and $A$.
Together with \eqref{u-upper} again, it implies
\begin{eqnarray*}
  \frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left|\log \left(\frac{u^{\Sigma_{k}}_{z_e(\widehat\Sigma_{k})}(\xi)}{C_0} \right)\ell(\xi) d\sigma \right|  d\sigma\leq C.
\end{eqnarray*}
Let $z_\star\coloneqq \lim\limits_{k\rightarrow +\infty}z_e({\widehat\Sigma_{k}})$. Since  the capillary entropy point $z_e({\widehat\Sigma_{k}})\in {\rm{int}}(\widehat{\partial\Sigma}_k)$ and $\lim\limits_{k\rightarrow +\infty}\widehat\Sigma_k =\widehat\Sigma_\star$, it follows that $z_\star\in \widehat{\partial\Sigma}_\star$. By Fatou's Lemma, we obtain 
\begin{eqnarray}\label{upper-lim}
  \frac{1}{\omega_{\theta}}\int_{\mathbb{S}^{n}_{\theta}}\log  \left(\frac{u^{\Sigma_\star}_{z_\star}(\zeta)}{C_0}\right)\ell(\zeta) d\sigma \geq \limsup\limits_{k\rightarrow +\infty}\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\log \left(\frac{u_{z_e(\widehat\Sigma_{k})}^{\Sigma_{k}}(\xi)}{C_0}\right)\ell(\xi) d\sigma,
\end{eqnarray}
which implies 
\begin{eqnarray}\label{sup}
    \mathcal{F}_{\theta}(\widehat{\Sigma}_{\ast})\geq \limsup\limits_{k\rightarrow +\infty}\mathcal{E}_{\theta}(\widehat\Sigma_k ).
\end{eqnarray}
In view of \eqref{inf} and \eqref{sup}, we conclude that the assertion \eqref{lim} holds.


 \textit{(2)} Now we move on to prove \eqref{dist} by arguing via contradiction. Suppose there exists a sequence $\{\widehat\Sigma_{l}\}_{l\geq 1}\subset \Gamma_{A}$ such that
\begin{eqnarray}
    {\rm{dist}}\left(z_e(\widehat\Sigma_{l}), \Sigma_{l}\right)\rightarrow 0,~{\rm{as}}~l\rightarrow \infty. \label{dist-1}
\end{eqnarray}
By the Blaschke selection theorem, see, e.g., \cite[Theorem 1.8.7]{Sch},
there exists a subsequence of $\{\widehat\Sigma_{l}\}_{l\geq 1}$, still denoted by $\{\widehat\Sigma_{l}\}_{l\geq 1}$, such that $\widehat\Sigma_l$ converges to $\widehat\Sigma_\star$ as $l\to +\infty$. Let $q_{0}\coloneqq\lim\limits_{l\rightarrow +\infty}z_e(\widehat\Sigma_{l})$. Since each $z_e(\widehat\Sigma_{l})\in\widehat{\partial\Sigma} _{l}\subset \partial{\mathbb{R}^{n+1}_{+}}$,  together with  \eqref{dist-1}, it yields that  \begin{eqnarray}\label{fact-q0-boundary}
    q_{0}\in \partial \Sigma_\star.
\end{eqnarray}  Furthermore, from \eqref{lim} and \eqref{upper-lim}, we have
\begin{eqnarray*}
    \mathcal{F}_{\theta}(\widehat{\Sigma}_{\star}) &=&\lim\limits_{l\rightarrow +\infty}\mathcal{E}_{\theta}(\widehat\Sigma_l )=\lim\limits_{l\rightarrow +\infty}\frac{1}{\omega_{\theta}}\int_{\mathcal{C}_{\theta}}\left(\log u^{\Sigma_{l}}_{z_e(\widehat\Sigma_{l})}(\xi)\right)\ell(\xi) d\sigma \\&\leq & \frac{1}{\omega_{\theta}}\int_{\mathbb{S}^{n}_{\theta}}\left(\log u_{q_{0}}^{\Sigma_\star}(\zeta)\right)\ell(\zeta) d\sigma\leq \mathcal{F}_{\theta}(\widehat{\Sigma}_{\star}),
\end{eqnarray*}
 which implies that $q_0$ is the  capillary entropy point of $\widehat{\Sigma}_{\star}$. By applying Proposition \ref{prop-small angle}, we know that the point $q_0 \in \text{int}(\widehat{\partial \Sigma}_\star)$. However, this contradicts \eqref{fact-q0-boundary}. Hence, we complete the proof.
